\label{thm:mangoldt}
Suppose that $x^{0.58+\varepsilon }\leqslant H\leqslant x$ and that $A\geqslant 1$ is a large constant. Then one has
\[
\Bigl| \sum_{x<n \leqslant x+H} \Lambda (n) e(n\alpha) \Bigr| \leqslant H(\log x)^{-A}
\] and 
\begin{equation}\label{ec1.1}
\Bigl| \sum_{x<n \leqslant x+H} \mu (n) e(n\alpha) \Bigr| \leqslant H(\log x)^{-A},
\end{equation}
unless there exists an integer $1\leqslant q\ll (\log x)^{O_A(1)}$ such that
\[
\left\| q\alpha\right\| \ll \frac{x(\log x)^{O_A(1)}}{H^2}.
\]

\label{cor}
Let $N$ be a large odd integer and assume that (\ref{eq-moment}) holds. Then, whenever $H\geqslant x^{0.58+\varepsilon}$ one has
$$\mathcal R(N,H)=3\mathfrak{S}(N)H^{2}(\log N)^{-3}+O(H^{2}(\log N)^{-4}).   $$

\label{thm:large-values}
Let $(a_{n})$ be a sequence of complex numbers with $\lvert a_{n}\rvert\leqslant 1$. Suppose that $W$ is a finite set of pairs $(t,\chi)$, where $t\in [T, T+U]$ and $\chi$ is a primitive character modulo $q$, such that whenever $(t,\chi)\neq (t',\chi')$ then either $\chi\neq \chi'$ or $\lvert t-t'\rvert\geqslant 1$. Assume that \begin{equation}\label{yy5}
\Big\lvert \sum_{N<n \leqslant 2N} a_{n}\chi(n) n^{it}\Big\rvert\geqslant V\end{equation} for all $(t,\chi)\in W$. Then,
\begin{equation}\label{rr4}
\lvert W\rvert\ll (\log 2qU)^{2} \big(N^{2}V^{-2}+qU\min(NV^{-2},N^{4}V^{-6})\big).\end{equation}
Moreover, suppose that $q\leqslant N^{6/5}$. Then, if $ (qU)^{2/3}\leqslant N\leqslant (qU)^{5/6}$ one has
\begin{equation}\label{pp9}
\lvert W\rvert\ll (\log 2qU)^{2}N^{2}V^{-2}+ (qU)^{\varepsilon}qU N^{12/5}V^{-4},\end{equation} and if $N>(qU)^{5/6}$ then 
\begin{equation}\label{pp91}
\lvert W\rvert\ll (\log 2qU)^{2}N^{2}V^{-2}+(qU)^{\varepsilon}(qU)^{1/2} N^{3}V^{-4}.\end{equation}

\label{lem:restrict-small-q0}

Let $f:\mathbb{Z}\to\mathbb{R}$ be a divisor-bounded  function.  Suppose that $\alpha =a/q-\beta$ and $q\leqslant H^{1-\varepsilon}$. Then one has
\begin{multline*}
\sum_{x<n \leqslant x+H} f (n) e(n\alpha) = O\bigl(  H \exp(-(\log x)^{1/3}) \bigr)\\
+\sum_{q_0q_1= q \atop q_0\leqslant \exp((\log x)^{1/2})}\frac{1}{\phi(q_1)} \sum_{\chi \,(\mathrm{mod}\,q_1)} C(a,\chi) \sum_{\frac{x}{q_0}<n \leqslant \frac{x+H}{q_0}} \chi(n) f(q_0n) e(\beta q_0n).	
\end{multline*}

\label{prop:small-beta} 
Let $f:\mathbb{Z}\to\mathbb{R}$ be a divisor-bounded  function and $x^{\varepsilon}\leqslant H\leqslant x^{1-2\varepsilon }$.
	Let $\alpha =\frac aq +\beta \in \mathfrak m$ with $|\beta| \leqslant \frac{x(\log x)^{A/3}}{H^2}$. Then the following bounds hold:
	\begin{enumerate}
		\item If $q\leqslant (\log x)^{A}$ one has
\begin{align}\label{jjc} M_{f}(\alpha)\ll &\frac{H(\log x)^{A/2}}{(xq)^{1/2}} \sum_{ \substack{ q=q_0q_1\\ q_0\leqslant \exp((\log x)^{1/2})}}\sum_{\chi\,(\mathrm{mod}\,q_{1})}\int_{2\pi \beta x-\frac{x(\log x)^{A}}{H}}^{2\pi \beta x+\frac{x(\log x)^{A}}{H}}\lvert D_{f}(1/2+it,\chi)\rvert dt+H(\log X)^{-A/2}.
\end{align}
\item  When $q> (\log x)^{A}$ and $ \lvert \beta \rvert>x/H^{2}$ then (\ref{jjc}) holds as well.
\item  If instead $q> (\log x)^{A}$ and $\lvert \beta \rvert\leqslant x/H^{2}$ then
\begin{align}\label{rrr} M_{f}(\alpha)\ll &\frac{H(\log x)}{(xq)^{1/2}}\sum_{ \substack{ q=q_0q_1\\ q_0\leqslant \exp((\log x)^{1/2})}}\sum_{\chi\,(\mathrm{mod}\,q_{1})}\int_{2\pi \beta x-\frac{x(\log x)^{A/50}}{H}}^{2\pi \beta x+\frac{x(\log x)^{A/50}}{H}}\lvert D_{f}(1/2+it,\chi)\rvert dt+H(\log x)^{-A/52}\end{align}


	\end{enumerate}

In light of Lemma~\ref{lem:restrict-small-q0}, it suffices to bound
\[
\sum_{q_0q_1= q \atop q_0\leqslant \exp((\log x)^{1/2})} \frac{1}{\phi(q_1)} \sum_{\chi \,(\mathrm{mod}\,q_1)} C(a,\chi)  \sum_{\frac{x}{q_0}<n \leqslant \frac{x+H}{q_0}} f(q_0n)\chi(n)  e(\beta q_0n).
\]
For each fixed factorisation $q=q_0q_1$, we shall set
\[
F_{q_1}(n) = f(q_0n) \frac{1}{\phi(q_1)} \sum_{\chi \,(\mathrm{mod}\,q_1)} C(a,\chi)  \chi(n).
\]
To obtain the bounds required above, it therefore suffices to estimate
\begin{align}\label{eq:function-F}
	\sum_{x/q_0<n \leqslant (x+H)/q_0} F_{q_1}(n) e(q_0\beta n)
\end{align}
for each factorisation $q=q_0q_1$.

We first deduce from Taylor expansion that
\[
e(q_0\beta n) =e(x\beta) e\Bigl( x\beta\bigl( \log q_0n -\log x +\frac{(q_0n-x)^2}{2x^2} \bigr) \Bigr)+ O \Bigl( \frac{|q_0n-x|^3|\beta|}{x^2} \Bigr).
\]
When $\frac{x}{q_0}<n \leqslant \frac{x+H}{q_0}$ the big O-term is bounded by $O(x^{-\varepsilon})$ provided that $H \leqslant x^{1-2\varepsilon }$ and $|\beta|\leqslant \frac{x(\log x)^{A/3}}{qH^2}$. Besides, we observe from the assumption  $|f|\leqslant d_{l}$ for some $l\in \mathbb{Z}$ and the orthogonality of characters that
\begin{equation}\label{kk1}
\bigl|  F_{q_1} (n) \bigr| \leqslant |f(q_0n)| \cdot \Bigl| \sum_{r\,(\mathrm{mod}\,q_1) \atop (r,q_1)=1} e\bigl( \frac{ar}{q_1} \bigr) {\bf1}_{n\equiv r \,(\mathrm{mod}\,q_1)} \Bigr| \ll d_{l}(q_0n).
\end{equation}
As a consequence,  Shiu's bound gives
\begin{align}\label{eq:n-xbeta}
\Bigl|  \sum_{\frac{x}{q_0}<n \leqslant \frac{x+H}{q_0}} F_{q_1}(n) e(q_0\beta n)  \Bigr| \leqslant 
\Bigl|  \sum_{\frac{x}{q_0}<n \leqslant \frac{x+H}{q_0}} F_{q_1} (n) n^{2\pi i \beta x} e\bigl(  \frac{(q_0n-x)^2\beta}{2x} \bigr) \Bigr| +O(H^{1-\varepsilon/2}).	
\end{align}
We first note that the big O-term is acceptable since $H^{1-\varepsilon/2}d(q) \ll H^{1-\varepsilon/3}$. Moreover,  the application of Perron's formula (cf.~\cite[Theorem 5.2 and Corollary 5.3]{MV}) with truncation height $T_{q}(\beta)=\frac{x(\log x)^{A}}{H}$ if we are in cases (1) or (2), and $T_{q}(\beta)=\frac{x(\log x)^{A/50}}{H}$ when we are in case (3) yields, for any $0<u \leqslant \frac{H}{q_0}$, that
\begin{align*}
\sum_{\frac{x}{q_0}<n \leqslant \frac{x}{q_0}+u} F_{q_1} (n) n^{2\pi i \beta x}	=&\frac{1}{2\pi i} \int_{\frac12-iT_{q}(\beta)}^{\frac12+iT_{q}(\beta)} \Bigl( \sum_{\frac{x}{q_0}<n\leqslant\frac{2x}{q_0}}\frac{F_{q_1}(n)}{n^{s-2\pi i \beta x}} \Bigr) \frac{(x+uq_0)^s -x^s}{sq_0^s} \,\mathrm{d} s 
\\
&+O\Big(\frac{H}{q_{0}(\log x)^{B_{q}}}\Big),
\end{align*}
where $B_{q}=11A/12$ if we are in cases (1) and (2), and $B_{q}=A/51$ otherwise.

We now claim that the following estimate holds uniformly for $ u\leqslant H/q_{0}$, namely,
\begin{align}\label{claim-1}
&\Big\lvert\sum_{\frac{x}{q_0}<n \leqslant \frac{x}{q_0}+u} F_{q_1} (n) n^{2\pi i \beta x}	\Big\rvert\nonumber\\
 \ll &\frac{q_0^{1/2}u(\log x)^{O(1)}}{(q_{1}x)^{1/2}} \sum_{\chi \,(\mathrm{mod}\,q_{1})}  \int_{2\pi \beta x-T_{q}(\beta)}^{2\pi \beta x+T_{q}(\beta)} \Bigl| \sum_{\frac{x}{q_{0}}<n\leqslant  \frac{2x}{q_{0}}}\frac{f(q_{0}n) \chi(n)}{n^{1/2+it}} \Bigr| \,\mathrm{d} t +Hq_{0}^{-1}(\log x)^{-B_{q}}.
\end{align}
In order to prove the desired estimate assuming the above, we introduce first
\[
h(u)=\sum_{\frac{x}{q_0}<n \leqslant \frac{x}{q_0}+u} F_{ q_{1}}(n) n^{2\pi ix\beta}.
\]
It follows from summation by parts that
\begin{align*}
\sum_{\frac{x}{q_0}<n \leqslant \frac{x}{q_0}+H/q_{0}} F_{q_1} (n) n^{2\pi i \beta x}	e\bigl(  \frac{(q_0n-x)^2\beta}{2x} \bigr)=& e\bigl( \tfrac{H^2\beta}{2x} \bigr) h(H/q_{0}) \\
&+2\pi i \int_{0}^{H/q_{0}} h(v) \frac{q_{0}v\beta}{x} e\bigl(  \frac{(q_0v)^2\beta}{2x} \bigr)\,\mathrm{d} v.
\end{align*}
The first term is acceptable by the claim \eqref{claim-1}. For the integral term, taking absolute values and applying \eqref{claim-1}, we obtain
\begin{align*}
\ll& \frac{|\beta|H}{x} \int_{0}^{H/q_{0}} |h(u)|   \,\mathrm{d} u\\
\ll& \frac{H^3|\beta| (\log x)}{q^{1/2}x^{3/2}} \sum_{\chi \,(\mathrm{mod}\,q_{1})} \int_{2\pi \beta x-T_{q}(\beta)}^{2\pi \beta x+T_{q}(\beta)}\Bigl| \sum_{\frac{x}{q_{0}}<n\leqslant  \frac{2x}{q_{0}}}\frac{f(q_{0}n) \chi(n)}{n^{1/2+it}} \Bigr|  \,\mathrm{d} t +\frac{H^{3}|\beta|}{q_{0}x(\log x)^{B_{q}}}.
                                                                                                                                                                                                                             
\end{align*}
If we are in cases (1) and (2) then the proposition clearly follows by inserting the assumption $|\beta|\leqslant \frac{x(\log x)^{A/3}}{H^2}$ in the above equation, recalling that $B_{q}=11A/12$ and summing over $q_{0}|q$. If instead we are in case (3), then combining the bound $\lvert \beta\rvert\leqslant x/H^{2}$ and the previous estimate and summing over $q_{0}|q$ delivers the desired result. 

It remains to prove \eqref{claim-1}. One  deduces from   Perron's formula that
	\begin{align*}
	&\sum_{\frac{x}{q_0}<n \leqslant \frac{x}{q_0}+u} F_{q_1} (n) n^{2\pi i \beta x} = \frac{1}{2\pi i}\int_{1/2-iT_{q}(\beta)}^{1/2+iT_{q}(\beta)} \sum_{n\sim x} \frac{F_{q_{1}}(n)n^{2\pi i x\beta}}{n^s}\frac{(\frac{x}{q_{0}}+u)^{s}-\big(\frac{x}{q_{0}}\big)^{s}}{ s}\,\mathrm{d} s\\
	&+ O\Bigl(  \sum_{\substack{\frac{x}{2q_0}<n \leqslant \frac{2x}{q_0}\\ n \neq x}} |F_{q_{1}}(n)| \Bigl( \min \left\{1,\frac{x}{q_{0}T_{q}(\beta)|\frac{x}{q_{0}}-n|}\right\}+\min\left\{1,\frac{x}{q_{0}T_{q}(\beta)|n-(x+H')/q_{0}|}\right\}  \Bigr) \Bigr)\\
	&+O\Bigl( \frac{x (\log x)^{O(1)}}{q_{0}T_{q}(\beta)} \Bigr).	
	\end{align*}
Splitting the range $[\frac{x}{2q_0}, \frac{2x}{q_0}]$ into two parts, namely $0<|n-(x/q_{0})|\leqslant x/(q_{0}T_{q}(\beta))$ and $|n-(x/q_{0})|>x/(q_{0}T_{q}(\beta))$ and using the estimate (\ref{kk1}), one may deduce that the error term is $O(x(\log x)^{O(1)}/(q_{0}T_{q}(\beta)))$. Consequently,
\begin{align*}
\sum_{\frac{x}{q_0}<n \leqslant \frac{x}{q_0}+u} F_{q_1} (n) n^{2\pi i \beta x} =& \frac{1}{2\pi i} \int_{-T_{q}(\beta)}^{T_{q}(\beta)} \sum_{n\sim \frac{x}{q_{0}}} \frac{F_{q_{1}}(n) n^{2\pi ix\beta}}{n^{1/2+it}} \frac{(\frac{x}{q_{0}}+u)^{1/2+it}-\big(\frac{x}{q_{0}}\big)^{1/2+it}}{ 1/2+it}\,\mathrm{d} t\\
&+ O(Hq_{0}^{-1}(\log x)^{-B_{q}}).	
\end{align*}
The main term in the above equation equals
\begin{align*}
   \frac{1}{\phi(q_{1})}\sum_{\chi \,(\mathrm{mod}\,q_{1})} C(a,\chi)\frac{1}{2\pi i} \int_{-T_{q}(\beta)}^{T_{q}(\beta)} \sum_{n\sim \frac{x}{q_{0}}} \frac{f(q_{0}n) \chi(n) n^{2\pi ix\beta}}{n^{1/2+it}} \frac{(\frac{x}{q_{0}}+u)^{1/2+it}-\big(\frac{x}{q_{0}}\big)^{1/2+it}}{ 1/2+it}\,\mathrm{d} t.
\end{align*}
We next observe that whenever $\text{Re}(s)=1/2$ then
\begin{align*}
\Bigl|   \frac{(\frac{x}{q_{0}}+u)^{s}-\big(\frac{x}{q_{0}}\big)^{s} }{s} \Bigr|\ll \frac{q_{0}^{1/2}u}{x^{1/2}}.
\end{align*}
Therefore, making the change of variables $\Im s+ 2\pi x\beta \to \Im s$, and combining the bound  $|C(a,\chi)|\leqslant q_{1}^{1/2 }$ with the previous estimate yields
\begin{align*}
\biggl|  \sum_{\frac{x}{q_0}<n \leqslant \frac{x}{q_0}+u} F_{q_1} (n) n^{2\pi i \beta x}   \biggr| &\ll \frac{q_{0}^{1/2}u(\log x)^{O(1)}}{(q_{1}x)^{1/2}} \sum_{\chi \,(\mathrm{mod}\,q_{1})} \frac{1}{2\pi i} \int_{2\pi ix\beta-T_{q}(\beta)}^{2\pi ix\beta+T_{q}(\beta)} \Big\lvert\sum_{n\sim x} \frac{f(q_{0}n) \overline {\chi(n)}}{n^{1/2+it}}\Big\rvert\,\mathrm{d} t.	
\end{align*}



This completes the proof of the proposition.

\label{lem:large-beta}
 Let $1 \leqslant H \leqslant x$ and $x/H^2\leqslant \beta \leqslant x^{\varepsilon}$. Suppose that $f:\mathbb{Z} \to \mathbb{R} $ is a function such that $|f(n)| \leqslant d_l(q) d_l(n)$ for some $l\in \mathbb{Z}$ and $q\leqslant H$. Then one has
 \begin{align*}
 	\sum_{x<n \leqslant x+H} f(n) e(n\beta) =&\frac{e^{i\pi /4}}{2\pi\sqrt{\beta x}} \int_{2\pi \beta x}^{2\pi \beta(x+H)} \Bigl( \sum_{x<n \leqslant x+H} f(n) n^{it} \Bigr) e^{it-it \log\frac{t}{2\pi \beta}} \,\mathrm{d} t\\
 	&+O\Bigl( (\log x)^{O_l(1)} d_l(q) \Bigl( \sqrt{x/\beta} +  H^2/x \Bigr) \Bigr).
 \end{align*}

\label{lem: produ-diri-poly}
Let $\mu_{\boldsymbol N}$ be as in \eqref{mobius-n}.
Let $\chi$ be a Dirichlet character of conductor $q_1$. 
If $q_0\leqslant \exp((\log x)^{1/2})$, then
\begin{align}\label{Dss}
D_{\mu_{\boldsymbol N}}(s,\chi) = \sum_{q_Rq_1'q_2\cdots q_{2k-1}=q_0}F_{\mathbf q,\mu_{\boldsymbol N}}(s,\chi);
\end{align}
where 
\begin{equation}\label{jjw}F_{\mathbf{q},\mu_{\boldsymbol N}}(s,\chi)=P(s,\chi)R_{\mathbf{q}}(s,\chi)N_{1,\mathbf{q}}(s,\chi)\cdots N_{2k-1,\mathbf{q}}(s,\chi),\end{equation} 
and $$P(s,\chi)=\sum_{p\in (P_{1},2P_{1}]}\chi(p)p^{-s},$$
$$  R_{\mathbf{q}}(s,\chi)=\sum_{ r\in \big(\frac{R}{q_{R}},2\frac{R}{q_{R}}\big] \atop (r,q_0/q_R)=1} \frac{a_{rq_{R}}\chi (r)}{r^{s}},\qquad N_{i,\mathbf{q}}(s,\chi)=\sum_{n_{i}\in \big(\frac{N_{i}}{q_{i}},2\frac{N_{i}}{q_{i}}\big] \atop \big(n_i,\frac{q_0}{q_Rq_1'\cdots q_i}\big)=1} \frac{a_{i}(q_{i}n_{i})\chi (n_{i})}{n_{i}^{s}}. $$

For convenience, set $g(n)=\chi(n)n^{-s}$ in the proof. Obviously, it is completely multiplicative. Switching the order of summation yields
\begin{align*}
D_{\mu_{\boldsymbol N}}(s,\chi)&= \sum_{n}g(n)\sum_{\substack{q_{0}n=prm_{1}\cdots m_{2k-1}\\ p\in (P_{1},2P_{1}]\ r\in (R,2R], m_{i}\in (N_{i},2N_{i}]}}a_{r}a_{1}(m_{1})\cdots a_{2k-1}(m_{2k-1})\\
&= \sum_{ \substack{p\in (P_{1},2P_{1}]\ r\in (R,2R], m_{i}\in (N_{i},2N_{i}] \\ q_0 \mid prm_1\cdots m_{2k-1}}} a_ra_1(m_1)\cdots a_{2k-1}(m_{2k-1}) g\big( \frac{prm_1\cdots m_{2k-1}}{q_0} \big)\\
&=\sum_{p\sim P_1} g(p) \sum_{ \substack{r\in (R,2R], m_{i}\in (N_{i},2N_{i}] \\ q_0 \mid rm_1\cdots m_{2k-1}}} a_ra_1(m_1)\cdots a_{2k-1}(m_{2k-1}) g\big( \frac{rm_1\cdots m_{2k-1}}{q_0} \big),
\end{align*}
 the last equation holding since $g$ is completely multiplicative, and since in view of the assumption that $q_0\leqslant \exp((\log x)^{1/2})$ then for any $p\in[P_1,2P_1]$, we always have $p>\exp((\log x)^{1/2})$, and hence $p\nmid q_{0}$. Therefore, we can replace the condition $q_0 \mid prm_1\cdots m_{2k-1}$ by $q_0 \mid rm_1\cdots m_{2k-1}$. 

Set $q_R=(r,q_0)$, $q_1'=(m_1,q_0/q_R),$ and $q_{i}=(m_1,q_0/q_R q_1'\cdots q_{i})$ whenever $2\leqslant i\leqslant 2k-1$. It then transpires that $q_0 \mid rm_1\cdots m_{2k-1}$ if and only if $q_R q_1'q_{2}\cdots q_{2k-1}=q_{0}$, and that there is a unique choice of the tuple $(q_R,q_1'\dots,q_{2k-1})$. After replacing $r/q_R$ by $r$ and $m_i/q_i$ by $n_i$, and using the completely multiplicativity of $g$, the preceding expression may be rewritten as
\begin{align*}
D_{\mu_{\boldsymbol N}}(s,\chi)&= \sum_{q_0=q_Rq_1' \cdots q_{2k-1}}\sum_{p \sim P_1} g(p) \sum_{r\sim \frac{R}{q_R} \atop (r,q_0/q_R)=1} a_{rq_R}g(r)\prod_{i\leqslant 2k-1} \sum_{ \substack{n_i\sim N_i/q_i \\ (n_i, \frac{q_0}{q_R q_1'\cdots q_i})=1} }  a_i(q_in_i) g(n_i)
\end{align*}
This gives \eqref{Dss} and completes the proof of the lemma.

We assume first that $q> (\log x)^{A}$, which in view of (\ref{eq6.1}) entails that $\lvert \beta\rvert\leqslant x/H^{2}$. By conjugating, and hence replacing $\beta$ with $-\beta$ if necessary, we may assume that $\beta$ is non-negative. The application of Proposition~\ref{prop:small-beta} (2) with $f=\mu_{\boldsymbol N}$ shows that it suffices to prove
\begin{align}\label{eq:typeii-large-q}
 \sum_{\substack{q=q_0q_1\\  q_0\leqslant \exp\bigl(  (\log x)^{1/2} \bigr)}} \sum_{\chi \,(\mathrm{mod}\,q_1)} \int_{2\pi \beta x-T_{q}(\beta)}^{2\pi \beta x+T_{q}(\beta)} \bigl|  D_{\mu_{\boldsymbol N}} (1/2+it,\chi) \bigr| \,\mathrm{d} t \ll (qx)^{1/2} (\log x)^{-A/10}.
\end{align}

For each factorization of $q_0$ as in the sums in~\eqref{Dss} given by the components of $\mathbf{q}=(q_R,q_1',q_2,\cdots q_{2k-1})$ we also write for the sake of concision
$$N_{2k,\mathbf{q}}(s,\chi)=P(s,\chi),\  \ \ \ \ \  \ \ \ \ \  \ \ \ \ \ \ \ \ N_{2k+1,\mathbf{q}}(s,\chi)=R(s,\chi),$$ and introduce
$$M_{1}(s,\chi)=\prod_{j\in J_{1}} N_{i,\mathbf{q}}(1/2+it,\chi),\  \ \  \ \ \ \ \ \ M_{2}(s,\chi)=\prod_{j\in J_{2}} N_{i,\mathbf{q}}(1/2+it,\chi).$$
It then follows from Lemma~\ref{lem:mean-value}, Lemma~\ref{lem: produ-diri-poly} and Cauchy-Schwarz inequality that
\begin{align*}
& \sum_{\substack{q=q_0q_1\\  q_0\leqslant \exp\bigl(  (\log x)^{1/2} \bigr)}} \sum_{\chi \,(\mathrm{mod}\,q_1)}\int_{2\pi \beta x-T_{q}(\beta)}^{2\pi \beta x+T_{q}(\beta)} \bigl|  D_{\mu_{\boldsymbol N}} (1/2+it,\chi) \bigr| \,\mathrm{d} t \\
&\ll \sum_{q=q_0q_1} \sum_{q_P q_R q_1'q_2\cdots q_{2k-1}=q_0} \sum_{\chi \,(\mathrm{mod}\,q_1)} \int_{2\pi \beta x-T_{q}(\beta)}^{2\pi \beta x+T_{q}(\beta)}\bigl| M_1(1/2+it,\chi) \bigr| \bigl| M_2(1/2+it,\chi) \bigr| \,\mathrm{d} t\\
&\ll  (\log x)^{A/49}  \sum_{\substack{q_0q_1=q\\ r_1r_2=q_0}} d_{2k+1}(r_1)d_{2k+1}(r_2) \bigl( \frac{q_1x}{H} +\frac{M_1}{r_1} \bigr)^{1/2} \bigl( \frac{q_1x}{H} +\frac{M_2}{r_2} \bigr)^{1/2}.	
\end{align*}
Using the assumptions $M_1,M_2\ll H x^{-\varepsilon^2}$, $M_1M_2\asymp x$ and $H\geqslant x^{1/2+\varepsilon }$, it transpires that
\begin{align*}
& \sum_{\substack{q=q_0q_1\\  q_0\leqslant \exp\bigl(  (\log x)^{1/2} \bigr)}} \sum_{\chi \,(\mathrm{mod}\,q_1)} \int_{2\pi \beta x-T_{q}(\beta)}^{2\pi \beta x+T_{q}(\beta)} \bigl|  D_{\mu_{\boldsymbol N}} (1/2+it,\chi) \bigr| \,\mathrm{d} t \\
\ll &\sqrt{qx} (\log x)^{A/49}\Bigl(  
\frac{\sqrt{qx}}{H}\sum_{q_0\mid q}\frac{d_{4k+2}(q_0)}{q_0} 
+\frac{1}{\sqrt H}  \sum_{q_0\mid q}\frac{d_{4k+2}(q_0)}{q_0^{1/2}} \Bigl( \max\left\{M_1^{1/2},M_2^{1/2}\right\}  \Bigr)  \Bigr)\\
&+x^{1/2}(\log x)^{A/49}\sum_{q_0\mid q}\frac{d_{4k+2}(q_0)}{q_0}\ll (qx)^{1/2} (\log x)^{-A/10},
\end{align*}
where in the last inequality we employed the conditions $q\leqslant H^2/x(\log x)^{A/3}$ and the estimate $\sum_{q_{0}|q} d_{4k+2}(q_ {0})q_{0}^{-1/2}\ll \exp((\log x)^{1/2})$. This gives the desired estimate~\eqref{eq:typeii-large-q} whenever $q> (\log x)^{A}$.

We shall assume next that $q\leqslant (\log x)^A$. For the sake of concission, we shall omit writing for each integer $q_0\mid q$ the condition $q_0\leqslant \exp((\log x)^{1/2})$ in the corresponding summation. We introduce for further use
\[
G_{\mathbf{q}}(s,\chi)=\prod_{j\in J_{1}\setminus\{2k\}}  N_{i,\mathbf{q}}\Big(\frac{1}{2}+it,\chi\Big)\prod_{j\in J_{2}\setminus\{2k\}} N_{i,\mathbf{q}}\Big(\frac{1}{2}+it,\chi\Big).
\]
We observe first that since $\alpha\in\mathfrak m$ and $q\leqslant (\log x)^{A}$ then $\beta\geqslant \frac{(\log x)^{5A}}{H}$. Consequently, \begin{equation}\label{jhjh}2\pi  \beta x+T_{q}(\beta)\geqslant 2\pi  \beta x-T_{q}(\beta)\geqslant \frac{x(\log x)^{5A}}{H}\geqslant (\log x)^{4A}.\end{equation} One then deduces from Lemmas \ref{lem:bd-diri-prime} and \ref{lem: produ-diri-poly} that
\begin{align*}
D_{\mu_{\boldsymbol N}}(\frac{1}{2}+it,\chi)&\ll \sum_{q_Rq_1'q_1 \cdots q_{2k-1}=q_0} \bigl| P(\frac12+it,\chi) \bigr| \bigl| G_{\mathbf{q}}(\frac12+it,\chi) \bigr|\\
&\ll P_1^{1/2}\Bigl( \frac{\log x}{1+|t|} + \exp\bigl( -(\log x)^{\varepsilon_{0}/3} \bigr) \Bigr) \sum_{q_Rq_1'q_1 \cdots q_{2k-1}=q_0} \bigl| G_{\mathbf{q}}(\frac12+it,\chi) \bigr|\\
&\ll  P_1^{1/2} (\log x)^{-3A} \sum_{q_Rq_1'q_1 \cdots q_{2k-1}=q_0} \bigl| G_{\mathbf{q}}(\frac12+it,\chi) \bigr|.
\end{align*}
provided that $t\geqslant (\log x)^{4A}$, which is indeed the case in view of (\ref{jhjh}). Therefore, due to the above logrithmic-saving, one may deduce from Proposition~\ref{prop:small-beta} (1) that it suffices to prove the estimate
\begin{align}\label{eq:claim-typeii}
 \sum_{\substack{q=q_0q_1\\ q_Rq_1'q_1 \cdots q_{2k-1}=q_0}} \sum_{\chi\,(\mathrm{mod}\,q_1)} \int_{2\pi \beta x-T_{q}(\beta)}^{2\pi \beta x+T_{q}(\beta)}  \bigl| G_{\mathbf{q}}(\frac12+it,\chi) \bigr| \,\mathrm{d} t\ll \bigl( \frac{qx}{P_1} \bigr)^{1/2} (\log x)^{2A}.
\end{align}
 We assume without loss of generality that $2k\in J_1$. The application of Cauchy-Schwarz inequality and Lemma~\ref{lem:mean-value} gives
 \begin{align*}
 	& \sum_{\substack{q=q_0q_1\\ q_Rq_1'q_1 \cdots q_{2k-1}=q_0}} \sum_{\chi\,(\mathrm{mod}\,q_1)} \int_{2\pi \beta x-T_{q}(\beta)}^{2\pi \beta x+T_{q}(\beta)}  \bigl| G_{\mathbf{q}}(\frac12+it,\chi) \bigr| \,\mathrm{d} t\\
 	&\ll (\log x)^{A}  \sum_{\substack{q_0q_1=q\\ r_1r_2=q_0}} d_{2k+1}(r_1) d_{2k+1}(r_2) \bigl( \frac{q_1x}{H} +\frac{M_1}{P_1r_1} \bigr)^{1/2} \bigl(  \frac{q_1x}{H} + \frac{M_2}{r_2} \bigr)^{1/2}\\
 	&\ll (qx)^{1/2}q^{\varepsilon}(\log x)^{A}\Bigl(  \frac{(qx)^{1/2}}{H} + \frac{\max \left\{(M_1/P_1)^{1/2}, M_2^{1/2}\right\}}{H^{1/2}} +P_1^{-1/2}  \Bigr) \ll \bigl( \frac{qx}{P_1} \bigr)^{1/2} (\log x)^{2A},
 \end{align*}
where in the last line we used the fact that $P_1\leqslant \exp(\frac{\log x}{(\log \log x)^2})$ in conjunction with $M_1M_2\asymp x$, the condition $q\leqslant (\log x)^A$ and the assumptions $M_1,M_2\ll H x^{-\varepsilon^2}$ and $H\geqslant x^{1/2+\varepsilon }$. This gives~\eqref{eq:claim-typeii} and concludes the proof.

We first remark that the $x^\varepsilon$ loss in Lemma~\ref{lem:fourth-moment} prevents us from using the same Dirichlet approximation as in Section~\ref{sec:typei-ii}. We therefore take $Q=H^2/x^{1+\varepsilon}$ in~\eqref{eq:dirich-app}, so that $1\leqslant q\leqslant H^2/x^{1+\varepsilon}$ and
\begin{equation}\label{khkh}
q|\beta|=\left\| q\alpha\right\|\leqslant x^{1+\varepsilon}/H^2.
\end{equation}

As above, we may assume that $\beta$ is non-negative. We start by observing that the assumptions imply $N_{j_1},N_{j_2}\geqslant x^{1/20+\varepsilon}$. Indeed, otherwise, $(x/H)^{4/3+\varepsilon } \leqslant N_{j_1}N_{j_2} \leqslant x^{1/20+\varepsilon }(x/H)^{1+\varepsilon }$, which contradicts the proviso $H\leqslant x^{17/20-4\varepsilon}$. Thus the corresponding Dirichlet polynomial coefficients satisfy $a_{j_1}=a_{j_2}=1$. As in the proof of Lemma~\ref{lem:typei}, we may therefore assume that for $l=1,2$ then
\[
\Big| N_{j_{l},\mathbf{q}}(\frac{1}{2}+it,\chi\Big)\Big|\ll \sum_{d_l \mid \frac{q_0}{q_R\cdots q_{j_l}}} d_l^{-1/2} \bigg| \sum_{n_{j_l}\sim\frac{N_{j_l}}{q_{j_l} d_l}} \frac{\chi(n_{j_l})}{n_{j_l}^{1/2+it}}\bigg|.
\]
Since the integration ranges in Propositions~\ref{prop:small-beta} and~\ref{pro:large-beta} depend on the size of $\beta$, we set for convenience
\[
F(\beta)=\begin{cases}T_{q}(\beta) \qquad &\text{ if } \beta\leqslant x(\log x)^{A/3}/H^2;\\
 	 2\beta H, & \text{ if } x(\log x)^{A/3}/H^2 < \beta\leqslant x^{1+\varepsilon }/(qH^2).
 	 \end{cases}\]
By these propositions, it now suffices to prove 
\begin{align*}
& \sum_{q_1,\chi} \int_{2\pi \beta x-F(\beta)}^{2\pi \beta x+F(\beta)} \Bigl|  N_{j_{1},\mathbf{q}}(\frac{1}{2}+it,\chi\Big) N_{j_{2},\mathbf{q}}(\frac{1}{2}+it,\chi\Big)\prod_{j'\in[2k+1]\backslash\left\{j_1,j_2\right\}}  N_{j',\mathbf{q}}(\frac{1}{2}+it,\chi\Big) \Bigr|\,\mathrm{d} t\\
\ll& \sum_{q_1,\chi}  \sum_{\substack{d_1 \mid \frac{q_0}{q_R\cdots q_{j_1}}\\ d_2 \mid \frac{q_0}{q_R\cdots q_{j_2}}}} (d_1d_2)^{-1/2} \int_{2\pi \beta x-F(\beta)}^{2\pi \beta x+F(\beta)}\prod_{l=1,2} \bigg| \sum_{n_{j_l}\sim\frac{N_{j_l}}{q_{j_l} d_l}} \frac{\chi(n_{j_l})}{n_{j_l}^{1/2+it}}\bigg| \biggl|  \prod_{j'\in[2k+1]\backslash\left\{j_1,j_2\right\}}  N_{j',\mathbf{q}}(\frac{1}{2}+it,\chi\Big) \biggr|\,\mathrm{d} t\\
\ll& \begin{cases}
 	\sqrt{qx}(\log x)^{-A}, \qquad&\text{ if $q,\beta$ are as in cases (1) and (2) in Proposition \ref{prop:small-beta}},\\
  (q \beta)^{\frac12}H (\log x)^{-A/10}, & \text{ if $q,\beta$ are as in case (3) in Proposition \ref{prop:small-beta}},\\
 	 (q \beta)^{\frac12}H (\log x)^{-A}, & \text{ if } x(\log x)^{A/3}/H^2 < \beta\leqslant x^{1+\varepsilon }/(qH^2),
 \end{cases}
 \end{align*}
where we used the symbol $\sum_{q_{1},\chi}$ to denote the sum $\sum_{q_0q_{1}=q}\sum_{q_{R}q_{1}'q_{2}\cdots q_{2k-1}=q_{0}}\sum_{\chi\,(\mathrm{mod}\,q_{1})}$.	 



We first assume that $2\pi\beta x\geqslant 4F(\beta)$. Since $N_{j_l}\leqslant x^{1+\varepsilon }/H$, it therefore transpires that $N_{j_l}^{2}(\beta x)^{-3}\ll 1\leqslant q_1 F(\beta)$. Consequently, applying Lemma~\ref{lem:fourth-moment}, we obtain, for $l=1,2$ the estimate
\begin{align}\label{eqz}
\sum_{\chi \,(\mathrm{mod}\,q_1)} \int_{2\pi \beta x-F(\beta)}^{2\pi \beta x+F(\beta)} \bigg| \sum_{n_{j_l}\sim\frac{N_{j_l}}{q_{j_l} d_l}} \frac{\chi(n_{j_l})}{n_{j_l}^{1/2+it}}\bigg|^4 \,\mathrm{d} t& \ll x^{\varepsilon } \bigl( q_{1}F(\beta) +q_1^{\frac{71}{96}}(\beta x)^{2/3} \bigr) +\frac{N_{j_l}^2}{(\beta x)^{3}}\\
& \ll x^{\varepsilon } \bigl( q_1F(\beta) +q_1^{\frac{71}{96}}( \beta x)^{2/3} \bigr)\nonumber.
\end{align}
We then deduce from H\"older's inequality, the above estimate and Lemma~\ref{lem:mean-value} that
\begin{align}\label{chi1}
& \sum_{q_1,\chi}  \sum_{\substack{d_1 \mid \frac{q_0}{q_R\cdots q_{j_1}}\\ d_2 \mid \frac{q_0}{q_R\cdots q_{j_2}}}} (d_1d_2)^{-1/2} \int_{2\pi \beta x-F(\beta)}^{2\pi \beta x+F(\beta)}\prod_{l=1,2} \bigg| \sum_{n_{j_l}\sim\frac{N_{j_l}}{q_{j_l} d_l}} \frac{\chi(n_{j_l})}{n_{j_l}^{1/2+it}}\bigg| \biggl|  \prod_{j'\in[2k+1]\backslash\left\{j_1,j_2\right\}}  N_{j',\mathbf{q}}(\frac{1}{2}+it,\chi\Big) \biggr|\,\mathrm{d} t\\
\ll& x^{\varepsilon } \sum_{q=q_0q_1} d(q_{0})^{2}d_{6k+3}(q_0) \bigl(  q_1F(\beta) +q_1^{\frac{71}{96}}( \beta x)^{2/3} \bigr)^{1/2} \Bigl( q_1F(\beta) + \frac{x}{N_{j_1} N_{j_2}} \Bigr)^{1/2}.\nonumber
                                                                                                                                                                                                                                      
\end{align}
Suppose first that $\beta \leqslant x(\log x)^{A/3}/H^2$ and $F(\beta)=T_{q}(\beta)$. Since $N_{j_1} N_{j_2}\gg (x/H)^{4/3+\varepsilon }$ and since (\ref{khkh}) holds, the preceding expression is bounded by
\begin{align}\label{jgjg}
\ll&x^\varepsilon (qx)^{1/2} \Bigl(  \frac{(qx)^{1/2}}{H} + \frac{x^{1/2}}{(HN_{j_1} N_{j_2})^{1/2}} + \frac{q^{\frac{7}{192}} (q\beta x)^{1/3}}{H^{1/2}} + \frac{q^{-\frac{89}{192}} (q\beta x)^{1/3} }{ (N_{j_1} N_{j_2})^{1/2}}  \Bigr)\nonumber\\
\ll & x^\varepsilon (qx)^{1/2} \bigl(  \frac{(qx)^{1/2}}{H} + \frac{(x/H)^{1/2}}{(x/H)^{2/3+\varepsilon}} + \frac{q^{7/192}x^{2/3}}{H^{7/6}} +\frac{x^{2/3}}
{H^{2/3}(x/H)^{2/3+\varepsilon}} \bigr)\nonumber\\
\ll & x^{-\varepsilon }	 (qx)^{1/2},
\end{align}
the last inequality following from the assumptions $q\leqslant H^2/x^{1+4\varepsilon}$ and $H\geqslant x^{121/210+\varepsilon }$. This gives the desired bound.

Suppose instead that $x(\log x)^{A/3}/H^2< \beta \leqslant x^{1+\varepsilon}/qH^2$, and hence $F(\beta)=2\beta H$. Using this upper bound on $\beta$, it follows that (\ref{chi1}) is bounded above by
\begin{align*}
&\ll x^\varepsilon (q\beta)^{1/2} H \Bigl(  (q\beta)^{1/2} +\sqrt{\frac{x}{HN_{j_1}N_{j_2}}} +\frac{q^{7/192}(q\beta x)^{1/3}}{H^{1/2}} +\frac{q^{-\frac{89}{192}}(q\beta x)^{1/3}}{(N_{j_1}N_{j_2})^{1/2}} \Bigr)	\\
&\ll x^{-\varepsilon }(q\beta)^{1/2} H,
\end{align*}
where we used the estimate (\ref{jgjg}) to bound the last three summands and the condition $H\geqslant x^{1/2+\varepsilon}$.




We next assume that $2\pi\beta x<4F(\beta)$. Note that then $q> (\log x)^{A}$, since $\alpha\mathfrak m$ and hence if $q\leqslant (\log x)^{A}$ one would have $\beta\geqslant (\log x)^{5A}/H$ and the above bound would not occur. Moreover, $\beta\leqslant x/H^{2}$, since otherwise $2\pi \beta x>F(\beta)$. By making a dyadic dissection of $[2\pi \beta x-F(\beta),2\pi \beta x+F(\beta)]$, in order to estimate (\ref{eqz}) it suffices to consider intervals $[T_{1},2T_{1}]$ with $0\leqslant T_{1}\ll F(\beta)$. Indeed, an application of Lemma \ref{lem:fourth-moment} enables one to obtain for $l=1,2$ the estimate

\begin{align*}
\sum_{\chi \,(\mathrm{mod}\,q_1)} \int_{T_{1}}^{2T_{1}}  \bigg| \sum_{n_{j_l}\sim\frac{N_{j_l}}{q_{j_l} d_l}} \frac{\chi(n_{j_l})}{n_{j_l}^{1/2+it}}\bigg|^4 \,\mathrm{d} t&\ll (\log x)^{O(1)}q_{1}T_{1} +\frac{N_{j_l}^2}{(1+T_{1}^{3})}.
\end{align*}
We then deduce from H\"older's inequality, the above estimate and Lemma~\ref{lem:mean-value} that
\begin{align*}
& \sum_{q_1,\chi}\sum_{\substack{d_1 \mid \frac{q_0}{q_R\cdots q_{j_1}}\\ d_2 \mid \frac{q_0}{q_R\cdots q_{j_2}}}} (d_1d_2)^{-1/2}  \int_{T_{1}}^{2T_{1}}\prod_{l=1,2}  \bigg| \sum_{n_{j_l}\sim\frac{N_{j_l}}{q_{j_l} d_l}} \frac{\chi(n_{j_l})}{n_{j_l}^{1/2+it}}\bigg| \biggl|  \prod_{j'\in[2k+1]\backslash\left\{j_1,j_2\right\}}  N_{j',\mathbf{q}}(\frac{1}{2}+it,\chi\Big) \biggr|\,\mathrm{d} t\\
\ll& q^{\varepsilon }(\log x)^{O(1)}  \bigl(  q_{1}T_{1}+\frac{N_{j_1}^2}{(1+T_{1}^{3})} \bigr)^{1/4}\bigl(  q_{1}T_{1}+\frac{N_{j_2}^2}{(1+T_{1}^{3})} \bigr)^{1/4} \bigl( q_1T_{1}+ \frac{x}{N_{j_1} N_{j_2}} \bigr)^{1/2}
\\
\ll &q^{\varepsilon}(\log x)^{O(1)}\Big(qT_{1}+ \frac{(qN_{j_1} N_{j_2})^{1/2}}{(1+T_{1})}+q^{3/4}\max(N_{j_1} ^{1/2},N_{j_2}^{1/2})+(qT_{1})^{1/2}\Big(\frac{x}{N_{j_1} N_{j_2}}\Big)^{1/2}
\\
&+\frac{x^{1/2}}{1+T_{1}^{3/2}}+q^{1/4}\max(N_{j_1} ^{1/2},N_{j_2}^{1/2})\Big(\frac{x}{(1+T_{1})N_{j_1} N_{j_2}}\Big)^{1/2}\Big)
\\\ll &q^{\varepsilon}(\log x)^{O(1)}\Big(qT_{q}(\beta)+ (qN_{j_1} N_{j_2})^{1/2}+q^{3/4}\Big(\frac{x}{H}\Big)^{1/2+\varepsilon}
\\
&+\Big((qT_{1})^{1/2}+q^{1/4}\Big(\frac{x}{H}\Big)^{1/2+\varepsilon}\Big)\Big(\frac{x}{N_{j_1} N_{j_2}}\Big)^{1/2}+\frac{x^{1/2}}{1+T_{1}^{3/2}}\Big),
                                                                                                                                                                                                                                      
\end{align*}
where we used that $N_{j_1}, N_{j_2}\ll (x/H)^{1+\varepsilon}$. We then note that by assumption, $N_{j_1} N_{j_2}\ll (x/H)^{2}\ll  x^{1-4\varepsilon}.$ Moreover, $N_{j_1} N_{j_2}\gg (x/H)^{4/3}\gg T_{q}(\beta)x^{-4\varepsilon}\gg T_{1}x^{-4\varepsilon}$ and $q^{1/4}\ll H^{1/2}x^{-1/4}$. Therefore, the preceding term is bounded above by
\begin{align*}(\log x)^{O(1)} \Big(q^{1+\varepsilon}T_{q}(\beta)+(qx)^{1/2}x^{-\varepsilon}+(qx)^{1/2+\varepsilon}\frac{H^{1/6}}{x^{1/6}}+\frac{q^{\varepsilon}x^{1/2}}{1+T_{1}^{3/2}}\Big).
\end{align*}
Since $H\leqslant x^{17/20}$ then the third term is $O((qx)^{1/2}x^{-\varepsilon})$. Moreover, recalling that $q> (\log x)^{A}$ one has $(\log x)^{O(1)}q^{\varepsilon}x^{1/2}(1+T_{1}^{3/2})^{-1}\ll q^{1/2}x^{1/2}(\log x)^{-A/3}$, which would suffice since $\beta\leqslant x/H^{2}$. It is also worth noting that $qT_{q}(\beta)\ll (qx)^{1/2-\varepsilon/2}$. Consequently, 
$$q^{1+\varepsilon}T_{q}(\beta)+ (qx)^{1/2}x^{-\varepsilon}+\frac{q^{\varepsilon}x^{1/2}}{1+T_{1}^{3/2}}\ll (qx)^{1/2}(\log x)^{-A/3}.$$ 
This completes the proof.

\label{lem:type-iii}

 

Let $\mu_{\boldsymbol N}$ be as in \eqref{mobius-n}.
	Suppose that there exists a disjoint partition $J_{1}\sqcup J_{2}\sqcup J_{3}=\{1,\ldots,2k+1\}$  and parameters 
\begin{equation}\label{jj}M_{1}=\prod_{j\in J_{1}}N_{j},\ \ \ \ \ \ \ \ \ \ \ \ M_{2}=\prod_{j\in J_{2}}N_{j},\ \ \ \ \ \ \ \ \ \ \ \ M_{3}=\prod_{j\in J_{3}}N_{j}, \end{equation}
such that  $M_{1}M_{2}M_{3}\asymp x$, $M_{2}\leqslant M_{1}$ and  \begin{equation}\label{uu} 
 M_{2}\gg (x/H)^{4/5+\varepsilon},\ \  \ \ \ x^{4/25}\ll M_{3}\ll x^{1/5}, \ \ \ \ \ \ M_1\ll H^{10} x^{-16/3-\varepsilon }\end{equation}
and 
\begin{equation}\label{bb13}M_{2}^{1/2}M_{3}\ll x^{2/5}.\end{equation}
Then, whenever $x^{29/50+\varepsilon }\leqslant H\leqslant X^{32/55}$ one has
$$\sup_{\alpha \in \mathfrak m} \Big|\sum_{x<n\leqslant x+H}\mu_{\boldsymbol N}(n)e(\alpha n)\Big|\ll H(\log x)^{-A}.$$

Set $Q=x^{2/25+\varepsilon}$ in~\eqref{eq:dirich-app}. As above, we may assume that $\beta$ is non-negative. Thus by Dirichlet approximation there exist $a\in\mathbb{Z}$ and $q\in\mathbb{N}$ with $(a,q)=1$ and such that 
\begin{equation}\label{sss}q\leqslant x^{2/25+\varepsilon},\ \ \ \ \ \ \ \ \ \ \ \ 0\leqslant \beta=\alpha-a/q\leqslant \frac{1}{qx^{2/25+\varepsilon}}.\end{equation} 
As in the proof of Lemma~\ref{lem:typei2}, we introduce for further convenience  the function $F(\beta)=T_{q}(\beta)$ if $\beta \leqslant x(\log x)^{A/3}/H^{2}$ and $F(\beta)=2\beta H$ if $\beta > x(\log x)^{A/3}/H^{2}$. Then, by a similar argument as in previous sections,
\begin{align*}&\sum_{ q_0q_1=q \atop q_0\leqslant \exp((\log x)^{1/2})}\sum_{\chi\,(\mathrm{mod}\,q_{1})} \int_{2\pi \beta x-F(\beta)}^{2\pi \beta x+F(\beta)} \lvert D_{f}(1/2+it,\chi)\rvert dt\nonumber
\\
&\ll\sum_{q_{1},\chi}  \int_{2\pi \beta x-F(\beta)}^{2\pi \beta x+F(\beta)} \prod_{j\in J_{1}}\lvert  N_{i,\mathbf{q}}(1/2+it,\chi)\rvert \prod_{j\in J_{2}}\lvert  N_{i,\mathbf{q}}(1/2+it,\chi)\rvert \prod_{j\in J_{3}}\lvert  N_{i,\mathbf{q}}(1/2+it,\chi)\rvert dt,
\end{align*}
where $\sum_{q_{1},\chi}$ denotes the sum $\sum_{q_0q_{1}=q}\sum_{q_{P}q_{R}q_{1}'q_{2}\cdots q_{2k-1}=q_{0}}\sum_{\chi\,(\mathrm{mod}\,q_{1})}$ with the restriction $q_0\leqslant \exp((\log x)^{1/2})$. We then write
$$\prod_{j\in J_{1}} N_{i,\mathbf{q}}(s,\chi)=\sum_{m\sim M}a_{m}\chi(m)m^{-s},\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \prod_{j\in J_{2}} N_{i,\mathbf{q}}(s,\chi)=\sum_{n\sim N}b_{n}\chi(n)n^{-s}$$ and $$ \prod_{j\in J_{3}} N_{i,\mathbf{q}}(s,\chi)=\sum_{r\sim R}c_{r}\chi(r)r^{-s},$$ where $$M=M_{1}/r_{1},\ \ \ \ \ \ \ \ \ \ N=M_{2}/r_{2},\ \ \ \ \ \ \ \ \ \ R=M_{3}/r_{3}$$ and $r_{1}r_{2}r_{3}=q_{0}$, with $a_{m},b_{n},c_{r}$ being divisor-bounded functions. Meanwhile, since $q_0=r_1r_2r_3 \leqslant \exp((\log x)^{1/2})$ and $M_2\leqslant M_1$, we may assume, without loss of generality, that $N\leqslant M$.


Thus, in order to prove the lemma, Propositions~\ref{prop:small-beta} and \ref{pro:large-beta} reduce matters to showing that
\[
\sum_{q_0q_1=q \atop q_0\leqslant \exp((\log x)^{1/2})}
\sum_{q_{P}q_{R}q_{1}'q_{2}\cdots q_{2k-1}=q_{0}}
\sum_{\chi \,(\mathrm{mod}\,q_1)}
 \int_{2\pi \beta x-F(\beta)}^{2\pi \beta x+F(\beta)} 
\prod_{1\leqslant l\leqslant 3}\prod_{j\in J_l}
\lvert N_{i,\mathbf{q}}(1/2+it,\chi)\rvert \,dt
\]
is $O((qx)^{1/2}(\log x)^{-A})$ when
$\beta\leqslant x(\log x)^{A/3}/H^2$, and 
$O((q\beta)^{1/2}H(\log x)^{-A})$ when $\beta>x (\log x)^{A/3}/H^2$.
We now pass to a discretized formulation. We  say that a set $\mathcal S_{q_{1}}$ of pairs
$(t,\chi)$, where $t\in [2\pi \beta x-F(\beta),2\pi \beta x+F(\beta)]$ and $\chi$ is a character $\,(\mathrm{mod}\,q_1)$, is \emph{well-spaced} if, whenever
$(t_1,\chi),(t_2,\chi)\in\mathcal S_{q_{1}}$ with $t_1\neq t_2$, one has
\[
2\pi \beta x-F(\beta)<t_1,t_2<2\pi \beta x+F(\beta),
\qquad
|t_1-t_2|\geqslant 1.
\]
Let $s\in\mathbb C$ with $\Re s=1/2$ and $\Im s=t$. It therefore suffices to prove that, for any fixed $1/2\leqslant\sigma_1,\sigma_2,\sigma_3\leqslant1$ and any well-spaced set $\mathcal S_{q_{1}}$ such that every $(t,\chi)\in\mathcal S_{q_{1}}$ satisfies
\[
\Big\lvert \sum_{m\sim M}a_{m}\chi(m)m^{-s}\Big\rvert\asymp M^{\sigma_{1}-\frac12},\ \ \  \Big\lvert \sum_{n\sim N}a_{n}\chi(n)n^{-s}\Big\rvert\asymp N^{\sigma_{2}-\frac12},\ \ \\ \Big\lvert \sum_{r\sim R}a_{r}\chi(r)r^{-s}\Big\rvert\asymp R^{\sigma_{3}-\frac12},
\]
  one then has
 \begin{align}\label{small-beta}
  \sum_{q_0q_1=q }d_{6k+3}(q_{0})\lvert \mathcal S_{q_{1}}\rvert M^{\sigma_{1}}N^{\sigma_{2}}R^{\sigma_{3}}\ll q^{1/2 }x(\log x)^{-A}\quad \text{ if } 0\leqslant \beta\leqslant x (\log x)^{A/3}/H^2	;
\end{align}
and
 \begin{align}\label{large-beta}
 	 \sum_{q_0q_1=q }d_{6k+3}(q_{0})\lvert \mathcal S_{q_{1}}\rvert M^{\sigma_{1}}N^{\sigma_{2}}R^{\sigma_{3}}\ll \frac{(q\beta )^{1/2}Hx^{1/2}}{ (\log x)^{A}} \quad \text{ if } \beta> x(\log x)^{A/3}/H^2,
 \end{align}
 respectively. We shall divide the analysis into several cases according to the sizes of \(\beta\) and \(q\). In most of the occasions it will suffice to bound the sums over the divisor factors crudely by $d(q)d_{6k+3}(q)\ll q^\varepsilon$. We shall also write $\mathcal S$ for simplicity.
 






 
 \subsection*{Case 1. $\beta \leqslant x(\log x)^{A/3}/H^2$} 
In this context, we recall that \eqref{small-beta} is the desired estimate.  Applying \eqref{rr4} to the Dirichlet polynomial running over $m$,
we obtain
\[
|\mathcal{S}| \ll (\log x)^{O(1)}M^{2-2\sigma_1}
+x^{\varepsilon }\frac{qx}{H}M^{\min\{1-2\sigma_1,\,4-6\sigma_1\}}.
\]
Moreover, when $M\leqslant (qx/H)^{5/6}$, the assumptions
\[
q\leqslant x^{2/25+\varepsilon},\qquad
M\geqslant (x/H)^{4/5+\varepsilon},\qquad
H\leqslant x^{3/5}
\]
imply that
\[
(qx/H)^{2/3}
\leqslant \frac{x^{18/25+2\varepsilon/3}}{H^{2/3}}
\leqslant (x/H)^{4/5+2\varepsilon}
\leqslant M.
\]
Thus, in this regime, \eqref{pp9} gives
\[
|\mathcal{S}| \ll M^{2-2\sigma_1}(\log x)^{O(1)}
+\frac{qx^{1+\varepsilon }}{H}M^{12/5-4\sigma_1}.
\]
Combining the preceding two estimates, we obtain
\begin{equation}\label{eq1}
|\mathcal{S}| \ll M^{2-2\sigma_1} (\log x)^{O(1)}
+\frac{qx^{1+\varepsilon }}{H}M^{\min\{1-2\sigma_1,\,12/5-4\sigma_1,\,4-6\sigma_1\}},
\end{equation}
provided that $M\leqslant (qx/H)^{5/6}$. On the other hand, if $M\geqslant (qx/H)^{5/6}$ it transpires from \eqref{pp91} that
\begin{align}\label{m-large-gm}
|\mathcal{S}| \ll M^{2-2\sigma_1} (\log x)^{O(1)} + x^\varepsilon \big(\frac{qx}{H}\big)^{1/2} M^{3-4\sigma_1}.
\end{align}
 We now define some auxiliary functions $f_M$ and $h_M$ as follows. If
$M\leqslant (qx/H)^{5/6}$, set 
\begin{align}\label{f-q-large}
f_M(\sigma)=
\begin{cases}
1-2\sigma, & 1/2\leqslant \sigma\leqslant 7/10,\\
12/5-4\sigma, & 7/10\leqslant \sigma\leqslant 8/10,\\
4-6\sigma, & 8/10\leqslant \sigma\leqslant 1,
\end{cases} \qquad \text{and} \qquad  h_M(\sigma)=1.
\end{align}
If instead $M\geqslant (qx/H)^{5/6}$, we set
\[
f_M(\sigma)=
\begin{cases}
1-2\sigma, & \text{if $qx/H\leqslant M^{4-4\sigma}$},\\
3-4\sigma, & \text{otherwise},
\end{cases}
\qquad
h_M(\sigma)=
\begin{cases}
1, &  \text{if $qx/H\leqslant M^{4-4\sigma}$},\\
1/2, & \text{otherwise}.
\end{cases}
\]
For simplicity, we write $f$ and $h$ in place of $f_M$ and $h_M$ when no confusion can arise. Therefore, applying (\ref{eq1}) if $M\leqslant (qx/H)^{5/6}$, and \eqref{m-large-gm} and \eqref{rr4} when $M\geqslant (qx/H)^{5/6}$ one always has
\begin{align}\label{bound-m-small-beta}
|\mathcal{S}|
\ll M^{2-2\sigma_1} (\log x)^{O(1)}
+x^\varepsilon \left(\frac{qx}{H}\right)^{h(\sigma_1)}M^{f(\sigma_1)}.
\end{align}
Similarly, we have
 \begin{equation}\label{bound-n}
\lvert \mathcal{S}\rvert\ll N^{2-2\sigma_{2}} (\log x)^{O(1)}+ x^\varepsilon \Big(\frac{qx}{H}\Big)^{h_{N}(\sigma_{2})}N^{f_N(\sigma_{2})}.\end{equation}
For the $R$-polynomial, we notice first that for any positive integer $g$ one has from Montgomery--Hal\'asz--Huxley's large values estimates that
\begin{align}\label{r-large}
|\mathcal S| \ll x^\varepsilon (R^{2g(1-\sigma_3)} +\frac{qx}{H} R^{g(4-6\sigma_3)}).
\end{align}
Moreover, if one further has
$$\Big(\frac{qx}{H}\Big)^{2/3}\leqslant R^{g}\leqslant \Big(\frac{qx}{H}\Big)^{5/6}$$ then one may apply Theorem \ref{thm:large-values} to deduce that
\begin{equation}\label{bound-r-2}
 \lvert \mathcal{S}\rvert\ll R^{2g(1-\sigma_{3})} (\log x)^{O(1)}+\frac{qx^{1+\varepsilon }}{H}R^{gf(\sigma_{3})},\end{equation}
where $f(\sigma_3)$ is as in \eqref{f-q-large}. 
 
In what follows, we write $V=\sum_{q_0q_1=q }d_{6k+3}(q_{0})\lvert \mathcal{S}\rvert M^{\sigma_{1}}N^{\sigma_{2}}R^{\sigma_{3}}$. By (\ref{small-beta}) it suffices to prove that, for all $1/2\leqslant \sigma_1,\sigma_2,\sigma_3\leqslant 1$, then
\[
  V=\sum_{q_0q_1=q }d_{6k+3}(q_{0})\lvert \mathcal{S}\rvert M^{\sigma_{1}}N^{\sigma_{2}}R^{\sigma_{3}}\ll q^{1/2 } x (\log x)^{-A}.
\] 
We shall divide the analysis into four cases according to whether the diagonal terms dominate in \eqref{bound-m-small-beta} and in  \eqref{bound-n}.


                                                                                                 

                                                                                                                                                                                                                                                            

                                                                                                                              
                                                    
                                                                                                                                            
                                                 



                                                                                                                                               


                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                              
                                                                           
                                                                                                 



                                                                                                                                           

                                                                          


\subsection*{Case 1.1 } If
$M^{2-2\sigma_1}(\log x)^{O(1)} \geqslant x^\varepsilon \big(\frac{qx}{H}\big)^{h(\sigma_1)} M^{f(\sigma_1)}\text{ and }N^{2-2\sigma_2}(\log x)^{O(1)} \geqslant x^\varepsilon \big(\frac{qx}{H}\big)^{h(\sigma_2)} N^{f(\sigma_2)}.$
 We first assume that $q\geqslant (\log x)^{3A}$ and note from Cauchy-Schwarz inequality, \eqref{bound-m-small-beta} and \eqref{bound-n} that
\begin{align*}
 V& \ll (\log x)^{O(1)}  \sum_{q_0q_1=q }d_{6k+3}(q_{0}) \big(M^{2-2\sigma_1} N^{2-2\sigma_2}\big)^{1/2} M^{\sigma_1} N^{\sigma_2} R
\\
&\ll (\log x)^{O(1)}x \sum_{q_0q_1=q } \frac{ d_{6k+3}(q_{0})}{q_0} \ll q^{1/2}x(\log x)^{-A}.
\end{align*}
If instead $q\leqslant (\log x)^{3A}$, observing that $a_r$ may be expressed as the Dirichlet convolution of $\mu, \log \cdot$ and $1_{[N_i,2N_i]}$ and deducing that $|t|>(\log x)^{4A}$ by employing a similar argument to that in (\ref{jhjh}), we have from Lemma \ref{lem:upper-bd-diri} that 
\begin{align}\label{pointwise-r}
\Big| \sum_{r\sim R} \frac{a_r \chi(r)}{r^{1/2+it}}\Big| \ll R^{1/2} (\log x)^{-3A/2},
\end{align}
and therefore,
\begin{align*}
 V&\ll (\log x)^{O(1)} \sum_{q_0q_1=q }d_{6k+3}(q_{0})(M^{2-2\sigma_{1}}N^{2-2\sigma_{2}})^{1/2}M^{\sigma_{1}}N^{\sigma_{2}}R(\log x)^{-3A/2}
\\
&\ll (\log x)^{O(1)-3A/2}x \sum_{q_0q_1=q } \frac{ d_{6k+3}(q_{0})}{q_0} \ll q^{1/2}x(\log x)^{-A}.	
\end{align*}

\subsection*{Case 1.2 } If
$M^{2-2\sigma_1}(\log x)^{O(1)} \leqslant x^\varepsilon \big(\frac{qx}{H}\big)^{h(\sigma_1)} M^{f(\sigma_1)}\text{ and }N^{2-2\sigma_2}(\log x)^{O(1)} \leqslant x^\varepsilon \big(\frac{qx}{H}\big)^{h(\sigma_2)} N^{f(\sigma_2)}.$ 
As suggested by the definitions of $f(\sigma)$ and $h(\sigma)$, we must further decompose the estimates according to the size of $q$.

\subsection*{Case 1.2 (i)}
Suppose that $M,N\leqslant (qx/H)^{5/6}$. Then \eqref{bound-m-small-beta} yields
\[
|\mathcal S|\ll
\frac{qx^{1+\varepsilon }}{H}M^{f_M(\sigma_1)},
\]
where $f_M(\sigma_1)$ is as in
\eqref{f-q-large}; the analogous estimate holding with $N$ and
$\sigma_2$ in lieu of $M$ and $\sigma_1$. Hence, given any real number $1/4\leqslant a\leqslant 1/2$, one has
\begin{align}\label{a-sigma}
|\mathcal S|^a M^{\sigma_1} \ll x^\varepsilon (qx/H)^a M^{af(\sigma_1)+\sigma_1}\ll x^\varepsilon (qx/H)^a M^{\frac{7-4a}{10}}.
\end{align}
Here, the second bound follows by  noticing  from the definition of $f(\sigma)$ in \eqref{f-q-large} that for every $1/4\leqslant a< 1/2$, the inequality 
\[
af(\sigma) +\sigma \leqslant af(7/10) +7/10 =\frac{7-4a}{10}
\]
holds, where we essentially used the fact that the maximum of the left side of the above line is attained when $\sigma=7/10$.  

We first consider the range  $\Big(\frac{qx}{H}\Big)^{2/3}\leqslant R^{2}\leqslant \Big(\frac{qx}{H}\Big)^{5/6}$ so that \eqref{bound-r-2} is applicable. We may take $c_{1}=\frac{1}{4}$, $a_{1}=b_{1}=3/8$, and $c_{2}=1/8$, $a_{2}=b_{2}=7/16$. Then, using the  bound \eqref{a-sigma} for both the $M$-polynomial and $N$-polynomial,  in conjunction with \eqref{bound-r-2} for the choice $g=2$ to the $R$-polynomial gives
\begin{align*}
x^{-\varepsilon}V\ll&
\left(\frac{qx}{H}M^{f(\sigma_1)}\right)^{a_1}
\left(\frac{qx}{H}N^{f(\sigma_2)}\right)^{b_1}
\left(R^{4(1-\sigma_3)}\right)^{c_1}
M^{\sigma_1}N^{\sigma_2}R^{\sigma_3}\\
&+
\left(\frac{qx}{H}M^{f(\sigma_1)}\right)^{a_2}
\left(\frac{qx}{H}N^{f(\sigma_2)}\right)^{b_2}
\left(\frac{qx}{H}R^{24/5-8\sigma_3}\right)^{c_2}
M^{\sigma_1}N^{\sigma_2}R^{\sigma_3}\nonumber\\
=&
\left(\frac{qx}{H}\right)^{a_1+b_1}
M^{a_1f(\sigma_1)+\sigma_1}N^{b_1f(\sigma_2)+\sigma_2}R + \frac{qx}{H} M^{a_2f(\sigma_1)+\sigma_1}N^{b_2f(\sigma_2)+\sigma_2}R^{3/5}.\nonumber
\end{align*}
Consequently, it follows from the second estimate in \eqref{a-sigma} that
\begin{align*}
V \ll& x^\varepsilon \Big(\Big(\frac{qx}{H}\Big)^{a_{1}+b_{1}}(MN)^{\frac{7-4a_{1}}{10}}R+\frac{qx}{H}(MN)^{\frac{7-4a_{2}}{10}}R^{3/5}\Big)\\
 \ll& x^\varepsilon \Big(\Big(\frac{qx}{H}\Big)^{3/4}(MN)^{11/20}R
+\frac{qx}{H}(MN)^{21/40}R^{3/5} \Big)\\
\ll& q^{1/2} x^{1+\varepsilon } \Big( \frac{q^{1/4}x^{3/10}R^{9/20}}{H^{3/4}}+q^{1/2}x^{21/40}R^{3/40}H^{-1}\Big), 
\end{align*}
where in the last inequality we have used the fact that $MNR\ll x$.

Using the assumptions $q\ll x^{2/25+\varepsilon }$, $R\ll x^{1/5}$ (from \eqref{uu}), and $H\geqslant x^{29/50+\varepsilon }$, and rescaling $\varepsilon$ if necessary, we obtain
\[
V \ll q^{1/2} x^{1+\varepsilon } \big( x^{\frac1{50}+\frac3{10}+\frac9{100}-\frac{87}{200}+\varepsilon } +x^{\frac1{25}+\frac{21}{40}+\frac3{200}-\frac{29}{50}-\varepsilon/2 }\big)\ll q^{1/2}x^{1-\varepsilon/2 },
\]
as desired.



                                                                                                                                                             
                                                                                                                                                                               
                                                                              
                                                                                                                                     
                                                                                                                 

                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                        
   
                                                                                                                                                                                                                                        
   
                                                                                                                                                            
   
                                                                                                                                                                                         
            

                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                           
                                                                                                                                                        
   
                                                                                                          
             
                                             
                                                                                                                                
             




We next assume that  either $R\leqslant \Big(\frac{qx}{H}\Big)^{1/3}$ or  $R\geqslant (qx/H)^{5/12}$. Let $g\geqslant 1$ be an integer to be specified later. We now take $c_{1}=(2g)^{-1}$, $a_{1}=b_{1}=\frac{1}{2}(1-c_{1})$, and $c_{2}=(6g)^{-1}$, $a_{2}=b_{2}=\frac{1}{2}(1-c_{2})$ and apply the estimates in \eqref{bound-m-small-beta} and \eqref{r-large},  to obtain 
\begin{align}\label{bb89}
x^{-\varepsilon}V \ll& \Big(\Big(\frac{qx}{H}\Big)M^{f(\sigma_{1})}\Big)^{a_{1}} \Big(\Big(\frac{qx}{H}\Big)N^{f(\sigma_{2})}\Big)^{b_{1}}(R^{g(2-2\sigma_{3})})^{c_{1}}M^{\sigma_{1}}N^{\sigma_{2}}R^{\sigma_{3}}\nonumber
\\
&+\Big(\Big(\frac{qx}{H}\Big)M^{f(\sigma_{1})}\Big)^{a_{2}} \Big(\Big(\frac{qx}{H}\Big)N^{f(\sigma_{2})}\Big)^{b_{2}}\Big(\frac{qx}{H}R^{g(4-6\sigma_{3})}\Big)^{c_{2}}M^{\sigma_{1}}N^{\sigma_{2}}R^{\sigma_{3}}\nonumber
\\
=&\Big(\frac{qx}{H}\Big)^{a_{1}+b_{1}} M^{a_1f(\sigma_{1})+\sigma_1}N^{b_1f(\sigma_2)+\sigma_{2}}R+\frac{qx}{H}M^{a_{2}f(\sigma_{1})+\sigma_1} N^{f(\sigma_{2})b_{2}+\sigma_2}R^{2/3}.
\end{align}
Consequently, it follows from \eqref{a-sigma} and the fact that $MNR\ll x$ that
\begin{align*}
V &\ll \Big(\frac{qx}{H}\Big)^{2a_{1}}(MN)^{\frac{7-4a_{1}}{10}}R+\Big(\frac{qx}{H}\Big)(MN)^{\frac{7-4a_{2}}{10}}R^{2/3}
\\
&\ll \Big(\frac{qx}{H}\Big)^{1-\frac{1}{2g}}(MN)^{\frac{1}{2}+\frac{1}{10g}}R+\Big(\frac{qx}{H}\Big)(MN)^{\frac{1}{2}+\frac{1}{30g}}R^{2/3}
\\
&\ll q^{1/2}x^{1+\varepsilon } \big(\frac{q^{1/2-1/2g} x^{1/2-2/5g} R^{1/2-1/10g}}{ H^{1-1/2g}} +\frac{q^{1/2} x^{1/2+1/30g } R^{1/6-1/30g}}{H}\big),
\end{align*}
whence taking $g=3$ yields
\begin{align}\label{ttj}
V&\ll x^{1+\varepsilon }  q^{1/2}\Big(\frac{q^{1/3}x^{11/30}R^{7/15}}{H^{5/6}}+q^{1/2}x^{23/45}R^{7/45}H^{-1}\Big).
\end{align}

We shall then assume first that $R^3<qx/H$ and insert the above bound into the previous estimate to obtain 
$$V\ll  q^{1/2}x^{1+\varepsilon}\Big(\frac{q^{22/45}x^{47/90}}{H^{89/90}}+q^{149/270}x^{76/135}H^{-142/135}\Big).$$ Consequently, by the assumption $q\leqslant x^{2/25+\varepsilon}$, it transpires that 
$$V\ll  q^{1/2}x^{1+\varepsilon}\Big(\frac{x^{421/750+\varepsilon}}{H^{89/90}}+x^{683/1125}H^{-142/135}\Big).$$
The preceding bound is acceptable whenever $H\geqslant \max( x^{1263/2225+\varepsilon},x^{2049/3550+\varepsilon}),$ as desired. Note that both of the above exponents are $<29/50$.

We then assume instead that $q\leqslant R^{12/5}Hx^{-1}$. It follows from (\ref{ttj}) and the restriction $R\ll x^{1/5}$ at the statement of the proposition that
\[V\ll q^{1/2}x^{1+\varepsilon}\Big(\frac{x^{1/30}R^{19/15}}{H^{1/2}}+\frac{x^{1/90}R^{61/45}}{H^{1/2}}\Big)
\ll q^{1/2}x^{1+\varepsilon}(x^{43/150}H^{-1/2}+x^{127/450}H^{-1/2}),
\]
which delivers the desired result once $H\geqslant x^{43/75+\varepsilon}$ and $H\geqslant x^{127/225+\varepsilon}$.

\subsection*{Case 1.2 (ii)}
We suppose next that $N \leqslant (qx/H)^{5/6}\leqslant M$. Under the latter assumption, equation \eqref{bound-m-small-beta} shows that for any real number $1/4\leqslant a\leqslant 1/2$ one has
\[
|\mathcal S|^a M^{\sigma_1} \ll 
\begin{cases}
\big(qx^{1+\varepsilon }/H\big)^a M^{a(1-2\sigma_1)+\sigma_1} \qquad &\text{ if } \frac{qx}{H} \leqslant M^{4-4\sigma_1};	\\
\big(qx^{1+\varepsilon }/H\big)^{a/2} M^{a(3-4\sigma_1) +\sigma_1} &\text{ otherwise}.
\end{cases}
\]
We thus conclude that
\begin{align}\label{a-sigma-m-large}
|\mathcal S|^a M^{\sigma_1} \ll x^\varepsilon  M^{1-a} (qx/H)^{3a/2-1/4}
\end{align}
uniformly for $1/2\leqslant \sigma_1 \leqslant 1$ and $1/4\leqslant a\leqslant 1/2$, where we essentially used the fact that the maximum is attained when $qx/H \asymp M^{4-4\sigma_1}$. Since $N\leqslant(qx/H)^{5/6}$, inequality~\eqref{a-sigma} also holds with $M$ and $\sigma_1$ replaced by $N$ and $\sigma_2$, respectively.

We still assume first that $(qx/H)^{2/3} \leqslant R^2\leqslant (qx/H)^{5/6}$. A similar procedure as the one in Case 1.2 (i) would ultimately lead to a worse exponent for $H$, and hence one is forced to deploy a finer argument. Indeed, we then note that whenever $f(\sigma)$ is defined as in \eqref{f-q-large}, one has for any real $c\in [1/8,1/4]$ the inequality
\[
2cf(\sigma) +\sigma \leqslant 2cf(7/10) +7/10 =\frac{7-8c}{10}.
\]
Therefore, we conclude from the bound \eqref{bound-r-2} corresponding to the $R$-polynomial, the estimate \eqref{a-sigma-m-large}
for the $M$-polynomial, the estimate \eqref{a-sigma} for the $N$-polynomial, and the choice of parameters $(a_1,b_1,c_1)=(1/2,1/4,1/4)$ whenever the first term in \eqref{bound-r-2} dominates, and $(a_2,b_2,c_2)=(1/2,3/8,1/8)$ whenever the second one dominates, that
\begin{align*}
x^{-\varepsilon }V \ll & \Big( \big(\frac{qx}{H}\big)^{h(\sigma_1)} M^{f(\sigma_1)}\Big)^{a_1}	\Big(\frac{qx}{H} N^{f(\sigma_2)}\Big)^{b_1}	 \Big( R^{4-4\sigma_3}\Big)^{c_1}	M^{\sigma_1}N^{\sigma_2} R^{\sigma_3}\\
&+ \Big( \big(\frac{qx}{H}\big)^{h(\sigma_1)} M^{f(\sigma_1)} \Big)^{a_2}	\Big( \frac{qx}{H} N^{f(\sigma_2)}\Big)^{b_2}	 \Big( \frac{qx}{H} R^{2f(\sigma_3)}\Big)^{c_2}	M^{\sigma_1}N^{\sigma_2} R^{\sigma_3}\\
\ll& \big(\frac{qx}{H}\big)^{\frac{3a_1}{2}-\frac{1}{4}+b_1} M^{1-a_1} N^{\frac{7-4b_1}{10}} R+\Big(\frac{qx}{H}\Big)^{\frac{3a_2}{2} -\frac{1}{4}+b_2+c_2}  M^{1-a_2} N^{\frac{7-4b_2}{10}} R^{\frac{7-8c_2}{10}}
\\
\ll& \big(\frac{qx}{H}\big)^{3/4} M^{1/2} N^{3/5} R+\Big(\frac{qx}{H}\Big)M^{1/2} N^{11/20} R^{3/5}.
\end{align*}

Since $MNR \ll x$, we now bound the first term employing the assumptions $q\leqslant x^{2/25+\varepsilon }, R\ll x^{1/5}$ and $N \leqslant (qx/H)^{5/6}$. This then yields
\begin{align}\label{abc2}
V \ll & q^{1/2}x^{1+\varepsilon } \Big( \big(\frac{qx}{H^3}\big)^{1/4} N^{1/10} R^{1/2} +q^{1/2}H^{-1}x^{1/2}N^{1/20}R^{1/10}\Big)\nonumber\\
\ll& 	 q^{1/2}x^{1+\varepsilon } \Big( x^{23/50} H^{-5/6} +x^{\frac{27}{50}}H^{-1}N^{1/20}R^{1/10} \Big).
\end{align}
The first term is acceptable provided that $H\gg x^{0.58+\varepsilon }$. For the second one, one gets the desired bound whenever $N^{1/2}R\ll X^{2/5}$ and $H\gg x^{0.58+\varepsilon}$. This completes the analysis of the present case, since the latter condition follows from \eqref{bb13}.

We now assume that either $R \leqslant \big(\frac{qx}{H}\big)^{1/3}$ or $R\geqslant \big(\frac{qx}{H}\big)^{5/12}$. In this case, we apply the estimate \eqref{r-large} to the $R$-polynomial. Arguing as in \eqref{bb89} but using \eqref{a-sigma-m-large} to estimate the $M$-polynomial and taking $c_{1}=(2g)^{-1}$, $a_{1}=b_{1}=\frac{1}{2}(1-c_{1})$, and $c_{2}=(6g)^{-1}$, $a_{2}=b_{2}=\frac{1}{2}(1-c_{2})$, this gives
\[
V \ll x^\varepsilon \Big( \Big(\frac{qx}{H}\Big)^{\frac{3a_1}{2}-\frac{1}{4}+b_1} M^{1-a_1} N^{\frac{7-4b_1}{10}} R+ \Big(\frac{qx}{H}\Big)^{\frac{3a_2}{2} -\frac{1}{4}+b_2+c_2}  M^{1-a_2} N^{\frac{7-4b_2}{10}} R^{2/3} \Big).
\]
Consequently,
\[
V\ll x^\varepsilon\left(\big(\frac{qx}{H}\big)^{1-\frac{5}{8g}}
M^{\frac12+\frac{1}{4g}}
N^{\frac12+\frac{1}{10g}}R+
\big(\frac{qx}{H}\big)^{1-\frac{1}{24g}}
M^{\frac12+\frac{1}{12g}}
N^{\frac12+\frac{1}{30g}}R^{2/3}\right).
\]
Taking $g=3$ and recalling $MNR \ll x$, we then have
\begin{align}\label{f22}
V &\ll x^\varepsilon\left(\big(\frac{qx}{H}\big)^{19/24}M^{7/12}N^{8/15}R + \big(\frac{qx}{H}\big)^{71/72}M^{19/36}N^{23/45}R^{2/3}\right)\nonumber\\
&\ll q^{\frac{1}{2}}x^{1+\varepsilon}\left(
q^{\frac{7}{24}}x^{\frac{13}{40}}
M^{\frac{1}{20}}R^{\frac{7}{15}}H^{-\frac{19}{24}}+
q^{\frac{35}{72}}x^{\frac{179}{360}}
M^{\frac{1}{60}}R^{\frac{7}{45}}H^{-\frac{71}{72}}
\right).	
\end{align}



If $q\leqslant R^{12/5}H x^{-1}$, we have from the condition $M\ll H^{10} x^{-16/3-\varepsilon }$ in \eqref{uu} and $R\ll x^{1/5}$ that
\begin{align*}
V&\ll q^{\frac{1}{2}}x^{1+\varepsilon/2}\bigl( 
R^{\frac{7}{6}}x^{\frac{1}{30}}M^{\frac{1}{20}}H^{-\frac{1}{2}}
+R^{\frac{119}{90}}x^{\frac{1}{90}}M^{\frac{1}{60}}H^{-\frac{1}{2}} \bigr)
\\
&\ll q^{\frac{1}{2}}x^{1+\varepsilon/2}(x^{4/15}M^{1/20}H^{-1/2}+x^{62/225}M^{1/60}H^{-1/2})\ll q^{\frac{1}{2}}x^{1+\varepsilon/2}\bigl( 
x^{-\varepsilon}+x^{\frac{14}{75}}H^{-\frac{1}{3}} \bigr),
\end{align*}
which is acceptable provided that $H\gg x^{14/25+\varepsilon }$.

It only remains to handle the case when $R^3<qx/H$. Inserting the preceding condition into (\ref{f22}) and employing the restriction $q\ll x^{2/25+\varepsilon},$ we notice that
\begin{align*}
V\ll& q^{1/2}x^{1+\varepsilon }\Big(  q^{161/360}x^{173/360}M^{1/20}H^{-341/360}
+q^{581/1080}x^{593/1080}M^{1/60}H^{-1121/1080}\Big)\\
\ll & q^{1/2}x^{1+\varepsilon }\Big( x^{1549/3000} M^{1/20} H^{-341/360} +x^{5329/9000} M^{1/60} H^{-1121/1080}\Big)
\\
\ll& q^{1/2}x^{1+\varepsilon }\Big( x^{749/3000}  H^{-161/360} +x^{4529/9000} H^{-941/1080}\Big)\ll q^{1/2}x^{1-\varepsilon },
\end{align*}
where in the last inequalities we used the provisos $M\ll H^{10} x^{-16/3-\varepsilon }$ and $H\gg x^{0.58 }$.


As we assumed that $N\leqslant M$, the case $M < (qx/H)^{5/6} \leqslant N$ would not occur, whence it only remains to examine the instance in which $ (qx/H)^{5/6}\leqslant \min(M, N)$.

\subsection*{Case 1.2 (iii)}
Suppose  that $ (qx/H)^{5/6}\leqslant M, N$. In such a situation, we merely apply Montgomery--Hal\'asz--Huxley's bound to the $R$-polynomial (equation \eqref{r-large}). We shall instead employ the estimate \eqref{a-sigma-m-large} for both the $N$ and the $M$-polynomial, and deduce by making the choices $c_{1}=(2g)^{-1}$, $a_{1}=b_{1}=\frac{1}{2}(1-c_{1})$, and $c_{2}=(6g)^{-1}$, $a_{2}=b_{2}=\frac{1}{2}(1-c_{2})$ that
\begin{align*}
x^{-\varepsilon }V \ll & \Big( \big(\frac{qx}{H}\big)^{h(\sigma_1)} M^{f(\sigma_1)}\Big)^{a_1}	\Big( \big(\frac{qx}{H}\big)^{h(\sigma_2)}  N^{f(\sigma_2)}\Big)^{a_1}	 \Big( R^{2g(1-\sigma_3)}\Big)^{c_1}	M^{\sigma_1}N^{\sigma_2} R^{\sigma_3}\\
&+ \Big( \big(\frac{qx}{H}\big)^{h(\sigma_1)} M^{f(\sigma_1)} \Big)^{a_2}	\Big(  \big(\frac{qx}{H}\big)^{h(\sigma_2)}  N^{f(\sigma_2)}\Big)^{a_2}	 \Big( \frac{qx}{H} R^{g(4-6\sigma_3)}\Big)^{c_2}	M^{\sigma_1}N^{\sigma_2} R^{\sigma_3}\\
\ll & \big( \frac{qx}{H}\big)^{3a_1-1/2}(MN)^{1-a_1} R + \big( \frac{qx}{H}\big)^{3a_2-1/2+c_2}(MN)^{1-a_2}R^{2/3}.
\end{align*}
We next note that $q\leqslant N^{6/5}H/x\ll (MN)^{3/5}H/x$ since $N\leqslant M$ by assumption. Therefore, the preceding bound combined with the condition $MN\ll x/R$, the proviso $x^{4/25 } \ll R\ll x^{1/5}$ and the choice $g=3$ yields
\begin{align*}
V&\ll q^{1/2}x^\varepsilon  \Big( q^{1/4} (x/H)^{3/4} (MN)^{7/12} R+ q^{17/36}(x/H)^{35/36}(MN)^{19/36} R^{2/3}\Big)\\
&\ll  q^{1/2}x^{1+\varepsilon}\Big(x^{-1/2}(NM)^{11/15}RH^{-1/2}+ x^{-1/2}H^{-1/2}(NM)^{73/90}R^{2/3}\Big)
\\
&\ll  q^{1/2} x^{1+\varepsilon } \Big(x^{7/30}R^{4/15} H^{-1/2} + x^{14/45}R^{-13/90} H^{-1/2}\Big)
\\
&\ll q^{1/2} x^{1+\varepsilon } \Big(x^{43/150} H^{-1/2} + x^{36/125} H^{-1/2}\Big)\ll  q^{1/2} x^{1-\varepsilon }
\end{align*}
provided that $H\geqslant x^{0.58 }$. This gives the desired bound.

\subsection*{Case 1.3 } If
$(\log x)^{O(1)} M^{2-2\sigma_1}\geqslant x^\varepsilon \big(\frac{qx}{H}\big)^{h(\sigma_1)} M^{f(\sigma_1)} \text{ and }N^{2-2\sigma_2}(\log x)^{O(1)} \leqslant x^\varepsilon \big(\frac{qx}{H}\big)^{h(\sigma_2)} N^{f(\sigma_2)}.$
Under these circumstances, we notice that the first term in  \eqref{bound-m-small-beta} dominates. Therefore, we have
\[
|\mathcal S| \ll (\log x)^{O(1)} M^{2-2\sigma_1};
\]
while for the $N$-polynomial, the classical bound \eqref{rr4} suffices, namely
\[
|\mathcal S|\ll\frac{qx^{1+\varepsilon}}{H}N^{g(\sigma_2)},
\]
where $g(\sigma_2) = \min\left\{1-2\sigma_2,4-6\sigma_2\right\}$. It then follows from \cite[(7.2.17)]{Har} that for any real $1/6\leqslant b\leqslant 1/2$ we have
\[
bg(\sigma) +\sigma \leqslant bg(3/4) +3/4=\frac{3-2b}{4}.
\]
In an analogous manner as above, we employ \eqref{r-large} for the $R$-polynomial. Therefore, as in the proof of case 3 (ii) of \cite[Lemma 7.3]{Har}, we apply H\"older's inequality for the choices $a_{1}=\frac{1}{2}$, $b_{1}=\frac{1}{2}-\frac{1}{2g}$, $c_{1}=\frac{1}{2g}$ and $a_{2}=\frac{1}{2}$, $b_{2}=\frac{1}{2}-\frac{1}{6g}$, $c_{2}=\frac{1}{6g}$. This gives
\begin{align*}
V \ll & x^\varepsilon \Big( MR (qx/H)^{\frac{1}{2}-\frac{1}{2g}} N^{\frac{1}{2}+\frac{1}{4g}} + MR^{2/3} (qx/H)^{\frac{1}{2}} N^{\frac{1}{2}+\frac{1}{12g}}\Big)\\
\ll & q^{1/2} x^{1+\varepsilon } \Big( (x/H)^{\frac{1}{2}-\frac{1}{2g}} N^{-\frac{1}{2}+\frac{1}{4g}} + x^{1/6}H^{-\frac{1}{2}} M^{1/3} N^{-\frac{1}{6}+\frac{1}{12g}} \Big),	
\end{align*}
where we employed the proviso $MNR\ll x$ in the second line and used the trivial bound $q^{-1/(2g)}\leqslant1$ in the first one. Now taking $g=3$ delivers
\[
V\ll q^{1/2} x^{1+\varepsilon } \Big( (x/H)^{1/3}N^{-5/12} + x^{1/6}M^{1/3} N^{-5/36}H^{-1/2} \Big).
\]
The first term is acceptable since, by \eqref{uu}, we have $N\gg (x/H)^{4/5+\varepsilon }$. For the second term, since $M\ll x/(NR)$, it transpires that
\[
M^{1/3}N^{-5/36}\ll x^{1/3} N^{-17/36} R^{-1/3}\ll x^{-22/225 }H^{17/45}\ll H^{1/2}x^{-1/6 -2\varepsilon },
\]
where in the penultimate inequality we have used that $N\gg (x/H)^{4/5+\varepsilon }$ and $R\gg x^{4/25 }$ from \eqref{uu}, the last inequality in the above line holding provided that $H\gg x^{31/55+10\varepsilon}$. Therefore, we are done in this case.


\subsection*{Case 1.4 }If $(\log x)^{O(1)}M^{2-2\sigma_1} \leqslant x^\varepsilon \big(\frac{qx}{H}\big)^{h(\sigma_1)} M^{f(\sigma_1)} \text{ and }(\log x)^{O(1)}N^{2-2\sigma_2} \geqslant x^\varepsilon \big(\frac{qx}{H}\big)^{h(\sigma_2)} N^{f(\sigma_2)}.$
 This case is symmetrical to Case 1.3, whence no further details are thereby required.

This completes the estimation of \eqref{small-beta} for all $1/2\leqslant \sigma_1,\sigma_2,\sigma_3\leqslant 1$. We now turn to the complementary range $\beta \geqslant x(\log x)^{A/3}/H^2$.


                                                                                                                                    
                                                                                                                                                                                                                                                                                             
                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                     
    
                                                                                                                                                                                                                                                           
   
                                                                                                                                                                                                         
             
                                                            
                                                                                                                                                                                                                   
                                                                                                                                                                                                                                 
                                                                                                                                                                                         
            

                                                          
                                                                                                                                  
                                                                                          
             
                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                              
                                                                                                                                         
                                                                                                  
             
                                                                                                                                                           

                                                                             
                                                                          
              
                                                                                                                                                                                                                         
                                                                                                                                                                                                                            
            
                                     
                        
                                                                                                                                          
                                                                                                                                        
                                                                                                                                                       
            

                                                  
                                                                                                                                                                   
                                                                                                            
             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
               
                                                                                                                                                                       
                                                                                                                        
                                                                                                            
             
                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                














                                                                                                                                                                                     
                                                                                                                                                                            
                                                                                                                                                                       
            
                              
               
                                                                                                                             
                                                                                                             
             
                                                                                                                                 
                                                                                                                            
                                                                             
             
                                                                        
                                                                                                                                     
            
                                                                           














                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                             
                                                                   
                                                                                                                                           
                                                                                                                                                  
                                                                                                                                             
                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                        
                                                                                                                                                                                                 

\subsection*{Case 2. $x(\log x)^{A/3}/H^2\leqslant \beta$} In this context one has $F(\beta)=2\beta H$, and the goal becomes to prove \eqref{large-beta} in this range. We first note that the Diophantine approximation conditions in \eqref{sss} entail that $q\beta\leqslant x^{-2/25-\varepsilon}$. Consequently, whenever $H\ll x^{32/55}$, one has
\[
(q\beta H)^{2/3} \leqslant H^{2/3} x^{-4/75 } \ll (x/H)^{4/5} \ll M.
\]
Thus, the lower-bound hypotheses on $M$ and $N$ required to apply \eqref{pp9} are satisfied. Arguing as in the preceding range, we apply Theorem \ref{thm:large-values} to the Dirichlet polynomials running over $m$, $n$ and $r$, the only change being that the assumption underlying \eqref{pp91} regarding the sizes of $N$ and $M$ is now $N,M>(q\beta H)^{5/6}$. More precisely, one gets analogous estimates to those in \eqref{bound-m-small-beta}-\eqref{bound-r-2}, namely
\begin{align} \label{bound-m-large-beta}
|\mathcal S| \ll (\log x)^{O(1)}M^{2-2\sigma_1}  + x^\varepsilon (q\beta H)^{h(\sigma_1)}M^{f(\sigma_1)},	
\end{align}
where if $M\leqslant (q\beta H)^{5/6}$ then   $f(\sigma_1)$ and $h(\sigma_1)$ are defined as in \eqref{f-q-large}; and otherwise one has
\[
f(\sigma_1)=
\begin{cases}
1-2\sigma_1, & q\beta H\leqslant M^{4-4\sigma_1},\\
3-4\sigma_1, & \text{otherwise},
\end{cases}
\qquad
h(\sigma_1)=
\begin{cases}
1, & q\beta H\leqslant M^{4-4\sigma_1},\\
1/2, & \text{otherwise}.
\end{cases}
\]
The same argument applied to the $N$-polynomial gives
\begin{align} \label{bound-n-large-beta}
|\mathcal S| \ll N^{2-2\sigma_2} (\log x)^{O(1)} + x^\varepsilon (q\beta H)^{h(\sigma_2)}N^{f(\sigma_2)}.	
\end{align}
For the $R$-polynomial, the Montgomery--Hal\'asz--Huxley's large values estimate delivers,  for every positive integer $g$, the bound
\begin{align}\label{r-large-beta-large}
|\mathcal S| \ll x^\varepsilon (R^{2g(1-\sigma_3)} +q\beta H R^{g(4-6\sigma_3)}).
\end{align}
Moreover, if 
$$(q\beta H)^{2/3}\leqslant R^{g}\leqslant (q\beta H)^{5/6}$$ then one may apply Theorem \ref{thm:large-values} to deduce that
\begin{equation}\label{bound-r-2-beta-large}
 \lvert \mathcal{S}\rvert\ll  (\log x)^{O(1)}R^{2g(1-\sigma_{3})}+x^\varepsilon q\beta HR^{gf(\sigma_{3})},\end{equation}
where $f(\sigma_3)$ is the piecewise-linear function defined in \eqref{f-q-large}. 
 
As before, set $V=\sum_{q_0q_1=q } d_{6k+3}(q_{0})\lvert \mathcal{S}\rvert M^{\sigma_{1}}N^{\sigma_{2}}R^{\sigma_{3}}$. To prove \eqref{large-beta}, it is enough to show that, uniformly for $1/2\leqslant \sigma_1,\sigma_2,\sigma_3\leqslant 1$, one has
\[
  V=\sum_{q_0q_1=q } d_{6k+3}(q_{0})\lvert \mathcal{S}\rvert M^{\sigma_{1}}N^{\sigma_{2}}R^{\sigma_{3}}\ll (q\beta x)^{1/2} H (\log x)^{-A}.
\] 
In an analogous manner, we divide the proof into four cases, according to whether the diagonal term dominates in each of \eqref{bound-m-large-beta} and \eqref{bound-n-large-beta}.

\subsection*{Case 2.1} If both the bound $(\log x)^{O(1)}M^{2-2\sigma_1}  \geqslant x^\varepsilon (q\beta H)^{h(\sigma_1)}M^{f(\sigma_1)}$ and its counterpart $(\log x)^{O(1)} N^{2-2\sigma_2}  \geqslant  x^\varepsilon (q\beta H)^{h(\sigma_2)}N^{f(\sigma_2)}.$
Suppose first that $q\geqslant(\log x)^{3A}$. Then, combining \eqref{bound-m-large-beta} and \eqref{bound-n-large-beta} with the Cauchy-Schwarz inequality, we obtain

\begin{align*}
 V& \ll (\log x)^{O(1)}  \sum_{q_0q_1=q }d_{6k+3}(q_{0}) \big(M^{2-2\sigma_1} N^{2-2\sigma_2}\big)^{1/2} M^{\sigma_1} N^{\sigma_2} R
\\
&\ll (\log x)^{O(1)}x \sum_{q_0q_1=q } \frac{ d_{6k+3}(q_{0})}{q_0} \ll q^{1/2}x(\log x)^{-A}\ll \frac{(q\beta x)^{\frac12}H }{ (\log x)^A},
\end{align*}
where in the last step we used the assumption $\beta \geqslant x(\log x)^{A/3}/H^2$. This proves the desired estimate in this case.

It remains to consider  $1\leqslant q\leqslant (\log x)^{3A}$.  In this range, the pointwise estimate \eqref{pointwise-r} provides an arbitrarily large logarithmic saving for the $R$-polynomial. Therefore, arguing as in Case 1.1 we obtain
\[
V\ll q^{1/2} x(\log x)^{-3A/2+O(1)} \ll (q\beta x)^{1/2}H (\log x)^{-A},
\]
where we used the condition $\beta \geqslant x(\log x)^{A/3}/H^2$.


\subsection*{Case 2.2} If both the bound $M^{2-2\sigma_1} (\log x)^{O(1)} \leqslant x^\varepsilon (q\beta H)^{h(\sigma_1)}M^{f(\sigma_1)}$ and its counterpart $N^{2-2\sigma_2} (\log x)^{O(1)} \leqslant  x^\varepsilon (q\beta H)^{h(\sigma_2)}N^{f(\sigma_2)}$ hold.  
\subsection*{Case 2.2 (i)} Suppose that $M,N \leqslant (q\beta H)^{5/6}$. In this case the functions $f(\sigma)$ and $h(\sigma)$ in estimates \eqref{bound-m-large-beta} and \eqref{bound-n-large-beta} are as in \eqref{f-q-large}. Therefore, in a similar manner as in \eqref{a-sigma}, one has for any real number  $1/4\leqslant a\leqslant 1/2$ the bound
\begin{align}\label{a-sigma-large-beta}
|\mathcal S|^a M^{\sigma_{1}} \ll x^\varepsilon (q\beta H)^a M^{af(\sigma_1)+\sigma_1}\ll x^\varepsilon (q\beta H)^{a}M^{\frac{7-4a}{10}}
\end{align}
for arbitrary $1/2\leqslant \sigma_1,\sigma_2\leqslant 1$. An analogous estimate holds as well for $N$.

As in the proof of Case 1.2 (i) we first assume that $ (q\beta H)^{2/3}\leqslant R^{2}\leqslant (q\beta H)^{5/6}$. It then follows from \eqref{bound-r-2-beta-large} that
\[
|\mathcal S| \ll x^\varepsilon \big( R^{4-4\sigma_3} + q\beta H R^{24/5-8\sigma_3}\big).
\]
Similarly as therein, we take $a_1=b_1=3/8,c_1=1/4$, and $a_2=b_2=7/16$, $c_2=1/8$ and deduce from the above estimates and  $MNR\ll x$ that
\begin{align*}
V \ll & x^{\varepsilon } \Big( (q\beta H)^{2a_1} M^{a_1f(\sigma_1)+\sigma_1}N^{a_1 f(\sigma_2)+\sigma_2}R + q\beta H M^{a_2f(\sigma_1)+\sigma_1}N^{a_2 f(\sigma_2)+\sigma_2} R^{3/5}\Big)\\
\ll & x^{\varepsilon } \big( (q\beta H)^{3/4} (MN)^{11/20} R+ q\beta H (MN)^{21/40} R^{3/5}\big)\\
\ll &  x^\varepsilon (q\beta x)^{1/2} H\big( (q\beta)^{1/4} x^{1/20} R^{9/20} H^{-1/4} +(q\beta)^{1/2} x^{1/40} R^{3/40}\big).	
\end{align*}
We now use the assumptions $q\beta \ll x^{-2/25-\varepsilon }$ and $R\ll x^{1/5}$ in conjunction with the condition $H\gg x^{0.58+\varepsilon}$ to obtain
\[
V \ll x^{\varepsilon/2} (q\beta x)^{1/2} H \big(x^{3/25-\varepsilon } H^{-1/4} +x^{-\varepsilon }\big) \ll  x^{-\varepsilon/2} (q\beta x)^{1/2} H,
\]
as desired.

We then consider the case in which either $R\leqslant (q\beta H)^{1/3}$ or $R\geqslant (q\beta H)^{5/12}$. Taking $c_1=1/6$, $a_1=5/12$ and $c_2=1/18$, $a_2=17/36$, we have by \eqref{bound-r-2-beta-large} for the choice $g=3$ and $MNR\ll x$  that
\begin{align}\label{ec135}
V &\ll x^\varepsilon \Big( (q\beta H)^{2a_1} M^{a_1f(\sigma_1)+\sigma_1}N^{a_1 f(\sigma_2)+\sigma_2} R +q\beta H M^{a_2f(\sigma_1)+\sigma_1}N^{a_2 f(\sigma_2)+\sigma_2} R^{2/3}\Big)\nonumber\\
&\ll x^\varepsilon \Big((q\beta H)^{2a_{1}}(MN)^{\frac{7-4a_{1}}{10}}R+(q\beta H)(MN)^{\frac{7-4a_{2}}{10}}R^{2/3}\Big)\nonumber
\\
&\ll  x^\varepsilon  \big((q\beta H)^{5/6} (MN)^{8/15} R+ q\beta H (MN)^{23/45} R^{2/3}\big)\nonumber\\
&\ll x^\varepsilon (q\beta x)^{1/2} H \big( (q\beta)^{1/3} x^{1/30} R^{7/15} H^{-1/6} +(q\beta)^{1/2} x^{1/90} R^{7/45}\big).
\end{align}
Suppose first that $R^3\leqslant q\beta H$. One then deduces from this assumption and $q\beta \ll x^{-2/25-\varepsilon }$ that
\begin{align*}
V \ll &x^{\varepsilon/2} (q\beta x)^{1/2} H \big((q\beta)^{22/45}x^{1/30}H^{-1/90}+(q\beta)^{149/270}x^{1/90}H^{7/135}\big)\\
&\ll x^{\varepsilon/2} (q\beta x)^{1/2} H \big( x^{-\varepsilon  }+ x^{-223/6750-\varepsilon  }H^{7/135}\big) \ll x^{-\varepsilon/2 } (q\beta x)^{1/2} H 
\end{align*}
provided that $H\ll x^{223/350}$, which holds in view of the restriction $H\ll x^{32/55}$.

On the other hand, suppose that $R \geqslant (q\beta H)^{5/12}$. Then $q\beta \leqslant R^{12/5}/H$, whence inserting this inequality and the assumption $R\ll x^{1/5}$ in (\ref{ec135}) we find that
\begin{align*}
V&\ll x^\varepsilon (q\beta x)^{1/2} H (x^{1/30}R^{19/15}H^{-1/2}+x^{1/90}R^{61/45}H^{-1/2})
\\
&\ll x^\varepsilon (q\beta x)^{1/2} H (x^{43/150} H^{-1/2} + x^{127/450}H^{-1/2} ).
\end{align*}
The preceding bound is acceptable whenever $H\gg x^{43/75+3\varepsilon }$, as desired. 

 

\subsection*{Case 2.2 (ii)} Suppose that $N \leqslant (q\beta H)^{5/6} \leqslant M$. Since $M\geqslant (q\beta H)^{5/6}$, one may apply \eqref{bound-m-large-beta} to the $M$-polynomial. Arguing as in \eqref{a-sigma-m-large}, we thus obtain
\begin{align}\label{sigma-m-ll}
	|\mathcal S|^a M^{\sigma_1} \ll x^\varepsilon M^{1-a} (q\beta H)^{\frac{3a}{2}-\frac{1}{4}}
\end{align}
 uniformly for  $1/2\leqslant \sigma_1\leqslant 1$ and $1/4\leqslant a\leqslant 1/2$.
 
 When $(q\beta H)^{2/3} \leqslant R^2 \leqslant (q\beta H)^{5/6}$, we make the choices $b_1=c_1=1/4, a_1=1/2$, and $a_2=1/2, b_2=3/8$ and $c_2=1/8$. Employing \eqref{sigma-m-ll} for the $M$-polynomial, the analogue of \eqref{a-sigma-large-beta} for the $N$-polynomial, and \eqref{bound-r-2-beta-large} with $g=2$ for the $R$-polynomial, and using the inequality after \eqref{a-sigma-m-large} and $MNR\ll x$, we obtain 
 \begin{align*}
V\ll& x^\varepsilon \big((q\beta H)^{\frac{3a_1}{2}-\frac{1}{4}+b_1} M^{1-a_1} N^{\frac{7-4b_1}{10}} R+(q\beta H)^{\frac{3a_2}{2}-\frac{1}{4}+b_2+c_2} M^{1-a_2} N^{\frac{7-4b_2}{10}} R^{\frac{7-8c_2}{10}}\big)\\
\ll& x^\varepsilon \big((q\beta H)^{3/4}M^{1/2} N^{3/5} R + q\beta H M^{1/2}N^{11/20} R^{3/5}\big)\\
\ll & x^\varepsilon (q\beta x)^{1/2} H \big((q\beta)^{1/4} H^{-1/4}N^{1/10} R^{1/2} +(q\beta)^{1/2} N^{1/20} R^{1/10}\big). 
\end{align*}
We then bound the first term using the assumptions $N \ll (q\beta H)^{5/6}$, $q\beta \ll x^{-2/25-\varepsilon}$ and  $R\ll x^{1/5}$; and the second one employing $q\beta \ll x^{-2/25-\varepsilon }$. This leads to 
\begin{align*}
V&\ll x^\varepsilon (q\beta x)^{1/2} H \big((q\beta)^{1/3} H^{-1/6}x^{1/10} +(q\beta)^{1/2} N^{1/20} R^{1/10}\big)
\\
&\ll x^\varepsilon   (q\beta x)^{1/2} H \big(x^{11/150-\varepsilon}H^{-1/6}+x^{-1/25-\varepsilon}N^{1/20}R^{1/10}\big),
\end{align*}
the first term being acceptable if $H\gg x^{1/2}$, and the second one being of the required size whenever $N^{1/2}R\ll x^{2/5}$, which was assumed in \eqref{bb13}.


If instead either $R\leqslant (q\beta H)^{1/3}$ or $R\geqslant (q\beta H)^{5/12}$, arguing as in Case 2.2 (i), we shall apply \eqref{bound-r-2-beta-large} with $g=3$ to the $R$-polynomial. Hence, the choices $(a_1,b_1,c_1)=(5/12,5/12,1/6)$ and $(a_2,b_2,c_2)=(17/36,17/36,1/18)$ combined with the condition $MNR\ll x$, deliver
\begin{align}\label{ec72}
V \ll & x^\varepsilon \big( (q\beta H)^{\frac{3a_1}{2}-\frac{1}{4}+b_1} M^{1-a_1} N^{\frac{7-4b_1}{10}} R+(q\beta H)^{ \frac{3a_2}{2}-\frac{1}{4}+b_2+c_2} M^{1-a_2} N^{\frac{7-4b_2}{10}} R^{2/3} \big)\nonumber\\
\ll& x^\varepsilon \big((q\beta H)^{19/24} M^{7/12}N^{8/15}R+(q\beta H)^{71/72}M^{19/36}N^{23/45}R^{2/3}\big)\nonumber\\
\ll& x^\varepsilon (q\beta x)^{\frac12} H \big( (q\beta)^{\frac{7}{24}} H^{-\frac{5}{24}} x^{\frac{1}{30}} M^{\frac{1}{20}} R^{\frac{7}{15}}
+(q\beta)^{\frac{35}{72}} H^{-\frac{1}{72}} x^{\frac{1}{90}} M^{\frac{1}{60}} R^{\frac{7}{45}} \big).	
\end{align}

We assume $q\beta H\leqslant R^{12/5}$ first. It then transpires by the above equation and the assumption $R\ll x^{1/5}$ that
\begin{align*}
V \ll& x^\varepsilon (q\beta x)^{1/2} H \big( x^{1/30} M^{1/20} R^{7/6} H^{-1/2} + x^{1/90} M^{1/60} R^{119/90} H^{-1/2}\big)\\
\ll&  x^\varepsilon (q\beta x)^{1/2} H \big( x^{4/15} M^{1/20} H^{-1/2} + x^{62/225} M^{1/60} H^{-1/2}\big)\\
\ll & x^\varepsilon (q\beta x)^{1/2} H \big( x^{-2\varepsilon} + x^{14/75}  H^{-1/3}\big)\ll x^{-\varepsilon} (q\beta x)^{1/2} H,
\end{align*}
the last inequalities following provided that $M\ll H^{10} x^{-16/3-40\varepsilon}$, which is assumed in \eqref{uu}, and $H\gg x^{0.58+\varepsilon }$.

If instead $R\leqslant (q\beta H)^{1/3}$, we insert the condition $q\beta \ll x^{-2/25-\varepsilon }$ into (\ref{ec72}) to derive that
\begin{align*}
V&\ll  x^\varepsilon (q\beta x)^{1/2} H \big(  (q\beta )^{161/360} H^{-19/360} x^{1/30} M^{1/20}  +(q\beta)^{581/1080} H^{41/1080} x^{1/90} M^{1/60} \big)
\\
&\ll  x^\varepsilon (q\beta x)^{1/2} H \big( x^{-11/4500}M^{\frac{1}{20}}H^{-19/360} +x^{-\frac{431}{13500}}M^{1/60}H^{41/1080} \big).
\end{align*}
This is acceptable when $M\ll H^{10}x^{-16/3-\varepsilon }$ and $x^{0.58+\varepsilon }\leqslant H \leqslant x^{0.59}$, since then 
\begin{align*}
V&\ll  x^\varepsilon (q\beta x)^{1/2} H \big( x^{-1211/4500}H^{161/360} +x^{-\frac{1631}{13500}}H^{221/1080} \big)\ll x^{-\varepsilon} (q\beta x)^{1/2} H,
\end{align*}
as desired.
\subsection*{Case 2.2 (iii)} Suppose that $M,N \geqslant (q\beta H)^{5/6}$. We shall apply inequality \eqref{sigma-m-ll} to both the M-polynomial and the $N$-polynomial. Arguing as in Case 1.2 (iii), we also apply \eqref{r-large-beta-large} with $g=3$ to the $R$-polynomial. It then follows by making the choices $(a_1,b_1,c_1)=(5/12,5/12,1/6)$ and $(a_2,b_2,c_2)=(17/36,17/36,1/18)$ that
\begin{align*}
V\ll &x^{\varepsilon } \big( (q\beta H)^{3a_1-1/2} (MN)^{1-a_1} R +(q\beta H)^{3a_2-1/2+c_2} (MN)^{1-a_2} R^{2/3}\big)	\\
\ll & x^\varepsilon (q\beta H)^{1/2}  \big( (q\beta H)^{1/4} (MN)^{7/12} R +(q\beta H)^{17/36}  (MN)^{19/36} R^{2/3}\big).
\end{align*}
We now remind the reader that $N\leqslant M$ and deduce from the bound $q\beta H\ll N^{6/5} \ll (MN)^{3/5}$ and $MNR\ll x$ that
\begin{align*}
V&\ll x^{\varepsilon}(q\beta x)^{1/2}H\Big(x^{-1/2}H^{-1/2}(NM)^{11/15}R+ x^{-1/2}H^{-1/2}(NM)^{73/90}R^{2/3}\Big)
\\
&\ll x^\varepsilon (q\beta x)^{1/2}H\big( x^{7/30} R^{4/15}H^{-1/2} +x^{14/45} R^{-13/90}H^{-1/2}\big).
\end{align*}
Recalling that $x^{4/25} \leqslant R\ll x^{1/5}$, one gets
\[
x^{7/30} R^{4/15} +x^{14/45} R^{-13/90} \ll x^{43/150}+x^{36/125}\ll H^{1/2}x^{-2\varepsilon}
\]
provided that $H\gg x^{72/125+8\varepsilon}$. This gives the desired bound as well.

\subsection*{Case 2.3} If both the bound 
$M^{2-2\sigma_1} (\log x)^{O(1)} \geqslant x^\varepsilon (q\beta H)^{h(\sigma_1)}M^{f(\sigma_1)}$ and its counterpart $N^{2-2\sigma_2} (\log x)^{O(1)} \leqslant  x^\varepsilon (q\beta H)^{h(\sigma_2)}N^{f(\sigma_2)}$ hold.
 For the $M$-polynomial, we have from \eqref{bound-m-large-beta} that
\[
|\mathcal S| \ll x^\varepsilon M^{2-2\sigma_1},
\]
and for the $N$-polynomial we shall merely utilise \eqref{rr4}, which entails that
\[
|\mathcal S| \ll x^\varepsilon q\beta H N^{\min\left\{1-2\sigma_2,4-6\sigma_2\right\}}.
\] 
The reader may note from Case 1.3 that for any real $1/6\leqslant b\leqslant 1/2$  and $1/2\leqslant \sigma_2\leqslant 1$ the following inequality 
\[
|\mathcal S|^b N^{\sigma_2}\ll x^\varepsilon (q\beta H)^b N^{b\min\left\{1-2\sigma_2,4-6\sigma_2\right\}+\sigma_2} \ll x^\varepsilon (q\beta H)^b N^{\frac{3-2b}{4}}
\] 
holds. We shall also apply \eqref{r-large-beta-large} with $g=3$ to the $R$-polynomial. The choices $(a_1,b_1,c_1)=(1/2,1/3,1/6)$ and $(a_2,b_2,c_2)=(1/2,4/9,1/18)$ in conjunction with the fact that $MNR\ll x$ then yield
\begin{align*}
V &\ll x^\varepsilon \big( (q\beta H)^{b_1} M N^{\frac{3-2b_1}{4}} R +(q\beta H)^{b_1+c_1} M N^{\frac{3-2b_2}{4}} R^{2/3} \big)\\
&\ll x^{\varepsilon }(q\beta x)^{1/2}H\big(x^{1/2}(q\beta)^{-1/6} H^{-2/3} N^{-5/12} +x^{1/2}H^{-1/2}N^{-17/36} R^{-1/3} \big).
\end{align*}
Using the proviso $\beta \geqslant x/H^2$ (as we are in Case 2) and $N\gg (x/H)^{4/5+6\varepsilon }$, one deduces that
\[
x^{1/2}(q\beta)^{-1/6} H^{-2/3} N^{-5/12} \ll x^{1/2} x^{-1/6} H^{1/3} H^{-2/3} (x/H)^{-1/3-\varepsilon }\ll x^{-2\varepsilon}
\]
which is acceptable. For the second term, using the aditional restraint $R\gg x^{4/25}$, one has
\[
x^{1/2}H^{-1/2}N^{-17/36} R^{-1/3} \ll (x/H)^{1/2-17/45} x^{-4/75+\varepsilon}\ll x^{31/450} H^{-11/90}\ll x^{-2\varepsilon }
\]
provided that $H\gg x^{31/55+90\varepsilon }$. Therefore, the desired bound also follows in this case.


\subsection*{Case 2.4} If 
$M^{2-2\sigma_1} (\log x)^{O(1)} \leqslant x^\varepsilon (q\beta H)^{h(\sigma_1)}M^{f(\sigma_1)} \&N^{2-2\sigma_2} (\log x)^{O(1)} \geqslant  x^\varepsilon (q\beta H)^{h(\sigma_2)}N^{f(\sigma_2)},$ the situation is symmetrical to the preceding Case 2.3, whence no further details are required.

\label{thm1}
Suppose that $(b_{n})$ is a sequence of complex numbers with $\lvert b_{n}\rvert\leqslant 1$ and $(t_{r})_{r\leqslant R}$ is a sequence of $1$-separated points in $[T, T+U]$ such that
$$\Big\lvert \sum_{n=N}^{2N}b_{n}n^{it_{r}}\Big\rvert\geqslant V$$ for all $r\leqslant R$. Then one has
\begin{equation}\label{rr44}
R\ll U^{\varepsilon} \big(N^{2}V^{-2}+U\min(NV^{-2},N^{4}V^{-6})\big).\end{equation} Moreover,
\begin{equation} \label{RR}R\ll U^{\varepsilon}(N^{2}V^{-2}+N^{18/5}V^{-4}+UN^{12/5}V^{-4}).\end{equation}

Let $\chi$ be a character $\,(\mathrm{mod}\,q)$ and $\rho=\beta+i\gamma$ be a non-trivial zero of $L(s,\chi)$. Then either
\begin{equation}\label{hhg}\Big\lvert \sum_{N\leqslant n\leqslant 2N}\frac{a(n)\chi(n)}{n^{\rho}}\exp\Big(-\frac{n}{Y}\Big)\Big\rvert\geqslant \frac{1}{3\log T}\ \ \ \ \ \ \ \ \ \text{for some $N=2^{j}\in [U^{\delta}, Y(\log T)^{2}]$}\end{equation} or
\begin{equation}\label{po}\Big\lvert \frac{1}{2\pi i}\int_{\text{Re$(s)$}=-\beta+1/2}Y^{s}\Gamma(s)M(\rho+s)L(\rho+s,\chi)ds\Big\rvert\geqslant \frac{1}{3}.\end{equation}
